import type { BankQuestion } from "@/lib/bank";

/** Planning, Budget and Fiscal Policy (Indian Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "eco-planning-budget-1", "question": "India’s First Five-Year Plan (1951–56) was based mainly on which growth model?", "options": ["Mahalanobis model", "Harrod–Domar model", "Lewis model", "Rostow model"], "answer": 1, "explanation": "The First Plan used the Harrod–Domar model, linking growth to the savings rate and capital–output ratio, and gave priority to agriculture and irrigation. The Mahalanobis model came with the Second Plan.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-2", "question": "In the Constitution of India, the Union Budget is called the:", "options": ["Appropriation Account", "Economic Survey", "Finance Bill", "Annual Financial Statement"], "answer": 3, "explanation": "Article 112 requires the President to lay an “Annual Financial Statement” before Parliament each year; the word “budget” does not appear in the Constitution.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-3", "question": "Who is the ex-officio Chairperson of NITI Aayog?", "options": ["The President", "The Prime Minister", "The Vice-Chairperson of NITI Aayog", "The Union Finance Minister"], "answer": 1, "explanation": "The Prime Minister chairs NITI Aayog; the Vice-Chairperson, appointed by the PM, runs it day to day.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-4", "question": "GST in India is best described as a:", "options": ["Origin-based production tax", "Destination-based consumption tax", "Tax on the wealth of firms", "Direct tax on business income"], "answer": 1, "explanation": "GST is collected at each stage with input tax credit, and the revenue goes to the state where the goods or services are finally consumed, so it is a destination-based tax on consumption.", "difficulty": "easy", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-5", "question": "Who presented independent India’s first Union Budget, on 26 November 1947?", "options": ["R.K. Shanmukham Chetty", "Liaquat Ali Khan", "John Mathai", "C.D. Deshmukh"], "answer": 0, "explanation": "R.K. Shanmukham Chetty, the first Finance Minister, presented it. John Mathai presented the first budget of the Republic (1950); Liaquat Ali Khan presented the 1946 interim government budget.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-6", "question": "Under GST, which tax is levied on an inter-state supply of goods or services?", "options": ["SGST alone", "IGST", "UTGST", "CGST and SGST together"], "answer": 1, "explanation": "Inter-state supplies (and imports) attract Integrated GST, collected by the Centre and shared with the destination state. Intra-state supplies attract CGST plus SGST (or UTGST).", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-7", "question": "Which Five-Year Plan had the theme “Towards Faster and More Inclusive Growth”?", "options": ["Ninth Plan (1997–2002)", "Twelfth Plan (2012–17)", "Eleventh Plan (2007–12)", "Tenth Plan (2002–07)"], "answer": 2, "explanation": "The Eleventh Plan aimed at faster and more inclusive growth. The Twelfth Plan added one word: “Faster, More Inclusive and Sustainable Growth”.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-8", "question": "“No tax shall be levied or collected except by authority of law” is laid down in which Article of the Constitution?", "options": ["Article 300A", "Article 280", "Article 265", "Article 112"], "answer": 2, "explanation": "Article 265 bars any tax without a law passed by the legislature. Article 112 is the Annual Financial Statement and Article 280 the Finance Commission.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-9", "question": "Effective revenue deficit, first used in the Union Budget 2011–12, is:", "options": ["Revenue deficit minus interest payments", "Fiscal deficit minus revenue deficit", "Fiscal deficit minus interest payments", "Revenue deficit minus grants given for the creation of capital assets"], "answer": 3, "explanation": "Effective revenue deficit removes from the revenue deficit the grants (mainly to states) that are spent on building capital assets. Fiscal deficit minus interest payments is the primary deficit.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-10", "question": "Which of the following is “charged” on the Consolidated Fund of India and so is not put to the vote of Lok Sabha?", "options": ["Salaries of Union ministers", "Salaries of members of Lok Sabha", "Expenditure on defence", "Emoluments and allowances of the President"], "answer": 3, "explanation": "Under Article 112(3), the President’s emoluments, salaries of the Speaker, judges of the Supreme Court, CAG and others are charged expenditure: discussed but not voted. Ministers’ salaries and defence spending are voted.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-11", "question": "The Planning Commission of India was set up in March 1950 by:", "options": ["An Ordinance of the President", "A resolution of the Union Cabinet", "A Constitutional Amendment", "An Act of Parliament"], "answer": 1, "explanation": "The Planning Commission was neither constitutional nor statutory; it was created by a Cabinet resolution. NITI Aayog was likewise set up by a Cabinet resolution in 2015.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-12", "question": "Who chairs the GST Council?", "options": ["The Prime Minister", "A state Finance Minister chosen by rotation", "The Union Finance Minister", "The Union Revenue Secretary"], "answer": 2, "explanation": "Under Article 279A the Union Finance Minister is the Chairperson; the Union Minister of State for Finance and the Finance Ministers of all states are members.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-13", "question": "The “Rolling Plan” of 1978–80 was introduced by:", "options": ["The Congress government of Rajiv Gandhi", "The Janata Party government of Morarji Desai", "The Congress government of Indira Gandhi", "The National Front government of V.P. Singh"], "answer": 1, "explanation": "The Janata government ended the Fifth Plan a year early in 1978 and adopted a rolling plan, an idea associated with Gunnar Myrdal. The Congress returned in 1980 and started a fresh Sixth Plan.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-14", "question": "Which Five-Year Plan was terminated a year ahead of schedule, in 1978?", "options": ["Fourth Plan", "Sixth Plan", "Third Plan", "Fifth Plan"], "answer": 3, "explanation": "The Fifth Plan (1974–79), with its focus on poverty removal and self-reliance, was ended in 1978 by the new Janata government, which brought in the rolling plan.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-15", "question": "The first Five-Year Plan launched after the 1991 reforms, which moved India towards indicative planning, was the:", "options": ["Eighth Plan (1992–97)", "Tenth Plan (2002–07)", "Seventh Plan (1985–90)", "Ninth Plan (1997–2002)"], "answer": 0, "explanation": "After two annual plans (1990–92), the Eighth Plan began in 1992 with human resource development as its focus and the state’s role shifting from direct control to indicative planning.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-16", "question": "A Gender Budget Statement was first included in the Union Budget in:", "options": ["2005–06", "2014–15", "1991–92", "2000–01"], "answer": 0, "explanation": "Gender budgeting began with the Union Budget 2005–06, showing allocations for schemes that benefit women.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-17", "question": "The Railway Budget was merged with the Union (General) Budget with effect from the Budget of:", "options": ["2014–15", "2015–16", "2017–18", "2019–20"], "answer": 2, "explanation": "The 92-year-old practice of a separate Railway Budget ended with the Budget for 2017–18, presented on 1 February 2017, the same year the presentation date moved to 1 February.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-18", "question": "The separation of the Railway Budget from the General Budget in 1924 followed the recommendation of the:", "options": ["Acworth Committee", "Royal Commission on Agriculture", "Simon Commission", "Hilton Young Commission"], "answer": 0, "explanation": "The Acworth Committee (1920–21) recommended separating railway finances; the separation came in 1924. The Hilton Young Commission led to the RBI.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-19", "question": "In the GST Council, what weightage does the vote of the Central Government carry?", "options": ["One-third of the total votes cast", "One-fourth of the total votes cast", "Half of the total votes cast", "Two-thirds of the total votes cast"], "answer": 0, "explanation": "The Centre has one-third weight and all states together two-thirds; a decision needs at least three-fourths of the weighted votes, so neither side can pass a proposal alone.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-20", "question": "A government’s total expenditure is ₹50 lakh crore, revenue receipts ₹35 lakh crore, non-debt capital receipts ₹3 lakh crore and interest payments ₹5 lakh crore. Its primary deficit is:", "options": ["₹15 lakh crore", "₹10 lakh crore", "₹7 lakh crore", "₹12 lakh crore"], "answer": 2, "explanation": "Fiscal deficit = 50 − (35 + 3) = ₹12 lakh crore. Primary deficit = fiscal deficit − interest = 12 − 5 = ₹7 lakh crore. ₹12 lakh crore is the fiscal deficit, not the primary deficit.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-21", "question": "Revenue receipts are ₹30 lakh crore and revenue expenditure ₹38 lakh crore, of which ₹3 lakh crore is grants for the creation of capital assets. The effective revenue deficit is:", "options": ["₹8 lakh crore", "₹11 lakh crore", "₹3 lakh crore", "₹5 lakh crore"], "answer": 3, "explanation": "Revenue deficit = 38 − 30 = ₹8 lakh crore. Effective revenue deficit = 8 − 3 = ₹5 lakh crore. Adding the grants (₹11 lakh crore) is the usual slip.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-22", "question": "When GST was introduced in 2017, states were guaranteed compensation for loss of revenue for a period of:", "options": ["Seven years", "Ten years", "Three years", "Five years"], "answer": 3, "explanation": "The GST (Compensation to States) Act, 2017 promised compensation for five years (to June 2022), assuming 14% annual growth in revenue, funded by a compensation cess on goods such as tobacco and luxury cars.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-23", "question": "The Contingency Fund of India is placed at the disposal of the:", "options": ["Comptroller and Auditor General", "Union Finance Minister", "President", "Parliament"], "answer": 2, "explanation": "Under Article 267, the Contingency Fund is at the disposal of the President, who can make advances from it for unforeseen expenditure pending authorisation by Parliament. It is operated by the Finance Ministry on the President’s behalf.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-24", "question": "The FRBM Review Committee, which in 2017 recommended a general government debt-to-GDP target of 60%, was chaired by:", "options": ["N.K. Singh", "C. Rangarajan", "Urjit Patel", "Bimal Jalan"], "answer": 0, "explanation": "The N.K. Singh committee proposed debt as the main fiscal anchor: 60% of GDP for general government (40% Centre, 20% states) and a 3% fiscal deficit for the Centre.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-25", "question": "Match the Five-Year Plan with its main emphasis: 1. First Plan  2. Second Plan  3. Fifth Plan  4. Eighth Plan; a. Removal of poverty and self-reliance  b. Rapid industrialisation with heavy industry  c. Human resource development after the reforms  d. Agriculture and irrigation", "options": ["1-d, 2-b, 3-a, 4-c", "1-b, 2-d, 3-a, 4-c", "1-d, 2-b, 3-c, 4-a", "1-a, 2-b, 3-d, 4-c"], "answer": 0, "explanation": "First Plan: agriculture and irrigation; Second: heavy industry (Mahalanobis); Fifth: Garibi Hatao and self-reliance; Eighth: human resource development in the post-1991 economy.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-26", "question": "How many of these statements about NITI Aayog are correct? I. It was set up on 1 January 2015 by a Cabinet resolution. II. It is a constitutional body. III. Its Governing Council includes the Chief Ministers of all states. IV. It allocates plan funds to states.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. NITI Aayog is neither constitutional nor statutory (II wrong), and unlike the Planning Commission it has no power to allocate funds; devolution is now via the Finance Commission and ministries (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-27", "question": "Assertion (A): The fiscal deficit shows the total borrowing requirement of the government in a year. Reason (R): Fiscal deficit equals total expenditure minus the sum of revenue receipts and non-debt capital receipts.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true. The gap between what the government spends and what it receives without borrowing can be filled only by borrowing, so the formula in R is exactly why the fiscal deficit measures borrowing.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-28", "question": "How many of these statements are correct? I. Alcoholic liquor for human consumption is kept out of GST by the Constitution itself. II. GST on petrol, diesel, crude oil, natural gas and ATF can be levied from a date recommended by the GST Council. III. Electricity is taxed under GST. IV. The 101st Amendment inserted Article 246A, giving the Centre and states concurrent power to levy GST.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. Article 366(12A) excludes alcoholic liquor; the five petroleum products are within GST in law but await a Council recommendation; Article 246A gives simultaneous taxing power. Electricity is outside GST (III wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-29", "question": "Which of the following is NOT a capital receipt of the Government of India?", "options": ["Recovery of loans given to states", "Interest received on loans given to states", "Proceeds from disinvestment", "Market borrowings"], "answer": 1, "explanation": "Interest received is income that creates no liability and does not reduce assets, so it is a revenue receipt. Disinvestment and loan recoveries reduce assets and borrowings create liabilities, so they are capital receipts.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-30", "question": "Arrange in chronological order: 1. Formation of NITI Aayog  2. Setting up of the National Development Council  3. Adoption of the Rolling Plan  4. Setting up of the Planning Commission", "options": ["2, 4, 3, 1", "4, 2, 3, 1", "4, 3, 2, 1", "4, 2, 1, 3"], "answer": 1, "explanation": "Planning Commission: March 1950; National Development Council: August 1952; Rolling Plan: 1978; NITI Aayog: January 2015.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-planning-budget-31", "question": "A government’s budget shows: total expenditure ₹4,000 crore, revenue expenditure ₹3,000 crore, revenue receipts ₹2,400 crore, recovery of loans ₹100 crore, disinvestment ₹50 crore and interest payments ₹500 crore. Its fiscal deficit and primary deficit are respectively:", "options": ["₹600 crore and ₹100 crore", "₹1,450 crore and ₹950 crore", "₹1,450 crore and ₹850 crore", "₹1,600 crore and ₹1,100 crore"], "answer": 1, "explanation": "Non-debt receipts = 2,400 + 100 + 50 = 2,550. Fiscal deficit = 4,000 − 2,550 = ₹1,450 crore. Primary deficit = 1,450 − 500 = ₹950 crore. ₹600 crore is the revenue deficit (3,000 − 2,400).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-32", "question": "How many of these statements about the FRBM framework are correct? I. The FRBM Act was passed in 2003 and came into force in 2004. II. Amendments in 2018 made the debt-to-GDP ratio the main fiscal anchor. III. An escape clause allows the fiscal deficit target to be exceeded by up to 0.5% of GDP on specified grounds. IV. A Medium-Term Fiscal Policy Statement must be laid before Parliament with the Budget.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Act (2003) took effect in July 2004; the Finance Act 2018 shifted the anchor to debt; the escape clause permits a 0.5 percentage-point deviation for war, national calamity, structural reforms and the like; the Medium-Term Fiscal Policy Statement is one of the statements required by the Act.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-33", "question": "Match the budget document with the Article of the Constitution: 1. Annual Financial Statement  2. Appropriation Bill  3. Supplementary grants  4. Vote on account; a. Article 114  b. Article 112  c. Article 115  d. Article 116", "options": ["1-b, 2-a, 3-c, 4-d", "1-b, 2-a, 3-d, 4-c", "1-a, 2-b, 3-c, 4-d", "1-b, 2-c, 3-a, 4-d"], "answer": 0, "explanation": "Article 112: Annual Financial Statement; Article 114: Appropriation Bills; Article 115: supplementary, additional or excess grants; Article 116: votes on account, votes of credit and exceptional grants.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-34", "question": "Assertion (A): A Money Bill can be introduced only in the Lok Sabha. Reason (R): The Rajya Sabha can delay a Money Bill for at most 14 days.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A. A follows from Article 109, which reserves the introduction of Money Bills to the Lok Sabha; the 14-day limit is a separate rule on how long the Rajya Sabha may hold such a bill.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-35", "question": "How many of these statements about the Five-Year Plans are correct? I. The Third Plan fell short of its targets mainly because of the wars of 1962 and 1965 and the drought of 1965–66. II. The Fourth Plan aimed at “growth with stability and progressive achievement of self-reliance”. III. The Ninth Plan was followed by two annual plans. IV. The Twelfth Plan (2012–17) was the last Five-Year Plan.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The two annual plans of 1990–91 and 1991–92 came after the Seventh Plan, not the Ninth (III wrong). After 2017 NITI Aayog replaced Five-Year Plans with a vision, strategy and action agenda.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-36", "question": "How many of these statements about the Union Budget process are correct? I. Since 2017 the Union Budget has been presented on 1 February. II. The Economic Survey is prepared under the Chief Economic Adviser in the Department of Economic Affairs. III. Demands for grants still undiscussed on the last allotted day are put to vote together through the “guillotine”. IV. Cut motions on demands for grants can be moved in the Rajya Sabha.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Demands for grants are voted only by the Lok Sabha, so cut motions can be moved only there (IV wrong); the Rajya Sabha may only discuss the budget.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-37", "question": "Assertion (A): Heavy government borrowing can reduce private investment. Reason (R): Government borrowing raises the demand for loanable funds and pushes up interest rates.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: this is the crowding-out effect. Higher interest rates make private projects costlier to finance, so some private investment is displaced.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-38", "question": "Match the committee with its subject: 1. Raja Chelliah Committee  2. Vijay Kelkar Task Force (2002)  3. N.K. Singh Committee (2017)  4. C. Rangarajan Expert Group (2014); a. Measurement of poverty  b. Review of the FRBM Act  c. Tax reforms after 1991  d. Direct and indirect tax reform", "options": ["1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a", "1-c, 2-b, 3-d, 4-a"], "answer": 2, "explanation": "Raja Chelliah chaired the Tax Reforms Committee (1991); Vijay Kelkar headed the task forces on direct and indirect taxes (2002); N.K. Singh reviewed the FRBM Act; the Rangarajan group re-estimated poverty in 2014.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-39", "question": "A dealer in one state buys goods for ₹10,000 plus 18% GST and sells them within the same state for ₹15,000 plus 18% GST. After input tax credit, how much CGST does the dealer deposit?", "options": ["₹450", "₹2,700", "₹900", "₹1,350"], "answer": 0, "explanation": "Output GST = 18% of 15,000 = 2,700; input credit = 18% of 10,000 = 1,800; net GST = 900. For an intra-state sale this is split equally into CGST and SGST, so CGST = ₹450. ₹900 is the total GST, not the CGST.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "eco-planning-budget-40", "question": "Which of the following taxes was NOT subsumed in GST?", "options": ["State VAT on most goods", "Service tax", "Basic customs duty on imports", "Central excise duty on most manufactured goods"], "answer": 2, "explanation": "GST replaced service tax, most central excise and state VAT, among others. Basic customs duty still applies to imports separately; only the countervailing and special additional duties on imports were replaced by IGST.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-planning-budget-41", "question": "Which was the last Five-Year Plan in India?", "options": ["Tenth Plan", "Eleventh Plan", "Twelfth Plan", "Thirteenth Plan"], "answer": 2, "explanation": "The Twelfth Plan (2012–17) was the last. After the Planning Commission was replaced by NITI Aayog in 2015, no new Five-Year Plan was launched.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-42", "question": "India's financial year runs from:", "options": ["1 January to 31 December", "1 April to 31 March", "1 July to 30 June", "1 October to 30 September"], "answer": 1, "explanation": "The Government of India's financial year runs from 1 April to 31 March; the Budget for it is now presented on 1 February.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "eco-planning-budget-43", "question": "The Second Five-Year Plan (1956–61), which stressed heavy industry, was based on the model of:", "options": ["Harrod and Domar", "P. C. Mahalanobis", "Arthur Lewis", "John Maynard Keynes"], "answer": 1, "explanation": "The Mahalanobis model gave priority to capital goods and heavy industry. The First Plan followed the Harrod–Domar model.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-44", "question": "The period 1966–69, when Annual Plans replaced a Five-Year Plan, is known as the:", "options": ["Rolling Plan period", "Plan Holiday", "Indicative Planning phase", "Green Revolution phase"], "answer": 1, "explanation": "After the Third Plan, wars and droughts led to three Annual Plans (1966–69), called the Plan Holiday. The Fourth Plan began in 1969.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-45", "question": "Income tax is an example of a:", "options": ["Direct tax", "Indirect tax", "Goods and services tax", "Customs duty"], "answer": 0, "explanation": "A direct tax is paid by the person on whom it is levied and cannot be shifted. GST and customs duty are indirect taxes.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "eco-planning-budget-46", "question": "An Outcome Budget, linking money spent to measurable results, was first presented by the Union Government in:", "options": ["1991–92", "2000–01", "2005–06", "2017–18"], "answer": 2, "explanation": "The first Outcome Budget was presented in 2005–06, the same year the Gender Budget Statement first appeared.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-47", "question": "In India, fiscal policy is framed mainly by the:", "options": ["Reserve Bank of India", "Ministry of Finance", "NITI Aayog", "SEBI"], "answer": 1, "explanation": "Fiscal policy (taxation, spending, borrowing) is the Government's, through the Ministry of Finance. Monetary policy is the RBI's.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-48", "question": "The tax proposals in the Union Budget are given legal effect through the:", "options": ["Appropriation Bill", "Finance Bill", "Vote on account", "Demands for grants"], "answer": 1, "explanation": "The Finance Bill carries the taxation proposals. The Appropriation Bill authorises withdrawal of money from the Consolidated Fund for expenditure.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-49", "question": "Who was the first Deputy Chairman of the Planning Commission?", "options": ["V. T. Krishnamachari", "Gulzarilal Nanda", "C. D. Deshmukh", "P. C. Mahalanobis"], "answer": 1, "explanation": "Gulzarilal Nanda was the first Deputy Chairman (1950); the Prime Minister, Jawaharlal Nehru, was the Chairman.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-50", "question": "Who was the first Vice-Chairperson of NITI Aayog?", "options": ["Rajiv Kumar", "Arvind Panagariya", "Suman Bery", "Amitabh Kant"], "answer": 1, "explanation": "Arvind Panagariya was the first Vice-Chairperson (2015–17). Amitabh Kant was its CEO; Rajiv Kumar and Suman Bery were later Vice-Chairpersons.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-51", "question": "The theme of the Twelfth Five-Year Plan (2012–17) was:", "options": ["Growth with social justice and equality", "Towards faster and more inclusive growth", "Faster, more inclusive and sustainable growth", "Growth with stability"], "answer": 2, "explanation": "The Twelfth Plan added ‘sustainable’ to the Eleventh Plan's theme of faster and more inclusive growth.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-52", "question": "The Laffer curve shows the relationship between:", "options": ["Inflation and unemployment", "Tax rates and tax revenue", "Income and inequality", "Money supply and prices"], "answer": 1, "explanation": "The Laffer curve suggests that beyond some point higher tax rates reduce total tax revenue. Inflation and unemployment are linked by the Phillips curve.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-53", "question": "Direct Benefit Transfer, which credits subsidies and welfare payments straight into beneficiaries' bank accounts, was launched in India on:", "options": ["1 April 2010", "1 January 2013", "15 August 2014", "1 July 2017"], "answer": 1, "explanation": "DBT began on 1 January 2013. The Jan Dhan Yojana (August 2014) and Aadhaar later formed the ‘JAM’ trinity that widened it.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-54", "question": "When a government's estimated receipts are exactly equal to its estimated expenditure, its budget is called a:", "options": ["Deficit budget", "Surplus budget", "Balanced budget", "Zero-based budget"], "answer": 2, "explanation": "A balanced budget has receipts equal to expenditure. A zero-based budget is a method of preparing estimates from scratch, not a type of balance.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-55", "question": "The Union Budget 2025–26 set the fiscal deficit target (Budget Estimate) at:", "options": ["3.0% of GDP", "4.4% of GDP", "4.9% of GDP", "5.1% of GDP"], "answer": 1, "explanation": "Budget 2025–26 placed the fiscal deficit at 4.4% of GDP, down from 4.8% in the revised estimate for 2024–25.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-56", "question": "In place of Five-Year Plans, NITI Aayog proposed a set of documents consisting of a:", "options": ["Ten-year plan and five-year review", "15-year vision, a 7-year strategy and a 3-year action agenda", "20-year perspective plan and annual plans", "5-year strategy and rolling annual plans"], "answer": 1, "explanation": "NITI Aayog's first Three-Year Action Agenda covered 2017–18 to 2019–20, within a longer strategy and vision.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-57", "question": "Because of political instability at the Centre, the Eighth Plan could not begin in 1990, and the years 1990–92 were covered by:", "options": ["The Rolling Plan", "Two Annual Plans", "The Seventh Plan extended by two years", "A Perspective Plan"], "answer": 1, "explanation": "Annual Plans were run for 1990–91 and 1991–92, and the Eighth Plan began in April 1992.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-58", "question": "The part of the government's borrowing that is met by borrowing from the Reserve Bank of India is called the:", "options": ["Primary deficit", "Revenue deficit", "Monetised deficit", "Effective revenue deficit"], "answer": 2, "explanation": "Monetised deficit is the increase in the RBI's net credit to the government. It adds to reserve money and so is the most inflationary way to finance a deficit.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-59", "question": "Ad hoc Treasury Bills, through which the RBI automatically financed the government's deficit, were discontinued from:", "options": ["1 April 1991", "1 April 1994", "1 April 1997", "1 April 2003"], "answer": 2, "explanation": "Under a 1994 agreement between the Government and the RBI, ad hoc Treasury Bills ended from 1 April 1997 and were replaced by Ways and Means Advances.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-60", "question": "The Union's tax revenue rises by 15% in a year in which nominal GDP rises by 10%. The tax buoyancy is:", "options": ["0.67", "1.0", "1.5", "2.5"], "answer": 2, "explanation": "Tax buoyancy = % change in tax revenue ÷ % change in GDP = 15 ÷ 10 = 1.5. A value above 1 means revenue grows faster than the economy.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-61", "question": "A government's fiscal deficit is 5% of GDP and its primary deficit is 1.5% of GDP. If GDP is ₹300 lakh crore, its interest payments are:", "options": ["₹4.5 lakh crore", "₹10.5 lakh crore", "₹15 lakh crore", "₹19.5 lakh crore"], "answer": 1, "explanation": "Interest payments = fiscal deficit − primary deficit = 5% − 1.5% = 3.5% of GDP. 3.5% of ₹300 lakh crore = ₹10.5 lakh crore.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-62", "question": "A tax levied on an activity that harms others, such as a carbon tax on pollution, in order to correct that harm, is called a:", "options": ["Progressive tax", "Pigouvian tax", "Proportional tax", "Windfall tax"], "answer": 1, "explanation": "A Pigouvian tax, named after A. C. Pigou, makes the polluter bear the external cost of a negative externality.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-63", "question": "Revenue that the government gives up through tax exemptions, deductions and incentives is shown in the Budget documents as the:", "options": ["Receipt Budget", "Statement of Revenue Impact of Tax Incentives (tax expenditure)", "Medium-Term Fiscal Policy Statement", "Expenditure Budget"], "answer": 1, "explanation": "This statement, often called the tax expenditure statement, estimates revenue foregone because of concessions in direct and indirect taxes.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-64", "question": "The 80th Amendment (2000) changed the sharing of Union taxes with the States by:", "options": ["Making income tax wholly a State tax", "Providing that the States get a share of the total pool of Union taxes, not just of income tax and excise duty", "Abolishing the Finance Commission", "Creating the GST Council"], "answer": 1, "explanation": "On the Tenth Finance Commission's ‘alternative scheme of devolution’, the 80th Amendment amended Article 270 so that all Union taxes (except cesses and surcharges) form a divisible pool.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-65", "question": "Under the GST rate rationalisation that took effect on 22 September 2025, most goods and services fall into two main slabs of:", "options": ["5% and 12%", "5% and 18%", "12% and 18%", "12% and 28%"], "answer": 1, "explanation": "The GST Council in September 2025 merged the 12% and 28% slabs, leaving 5% and 18% as the main rates, with a special 40% rate for a small set of sin and luxury goods.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-66", "question": "The Aspirational Districts Programme, run by NITI Aayog to improve the most backward districts on health, education, agriculture and other indicators, was launched in:", "options": ["2015", "2018", "2020", "2023"], "answer": 1, "explanation": "It was launched in January 2018 and covers over 100 districts ranked on real-time indicators. An Aspirational Blocks Programme followed in 2023.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-67", "question": "The Government of India first issued Sovereign Green Bonds, to finance green infrastructure projects, in:", "options": ["2015–16", "2019–20", "2022–23", "2024–25"], "answer": 2, "explanation": "The first Sovereign Green Bonds were auctioned by the RBI in January 2023, in the financial year 2022–23, following an announcement in the 2022–23 Budget.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-68", "question": "Match the plan with its author: A. Bombay Plan (1944) B. Gandhian Plan (1944) C. People's Plan (1945) D. Sarvodaya Plan (1950) — 1. Jayaprakash Narayan 2. M. N. Roy 3. S. N. Agarwal 4. A group of leading industrialists", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1"], "answer": 0, "explanation": "The Bombay Plan was drawn up by industrialists such as J. R. D. Tata and G. D. Birla; the Gandhian Plan by S. N. Agarwal; the People's Plan by M. N. Roy; and the Sarvodaya Plan by Jayaprakash Narayan.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-69", "question": "Match the type of grant with its description: A. Supplementary grant B. Excess grant C. Token grant D. Exceptional grant — 1. Granted for a special purpose that is not part of the current service of any year 2. A nominal sum voted for a new service when funds can be found by reappropriation 3. Money spent beyond the grant for a year, regularised after the Public Accounts Committee examines it 4. An extra amount needed in the current year for a service already provided for", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Supplementary and excess grants are under Article 115; exceptional grants and votes of credit under Article 116. A token grant is used to open a new service through reappropriation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-70", "question": "How many of these statements about cut motions are correct? I. A ‘disapproval of policy cut’ seeks to reduce a demand to ₹1. II. An ‘economy cut’ seeks to reduce a demand by a specified amount. III. A ‘token cut’ seeks to reduce a demand by ₹100. IV. Cut motions on demands for grants can be moved in the Rajya Sabha.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: demands for grants are voted only by the Lok Sabha (Article 113), so cut motions are moved only there.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-71", "question": "Assertion (A): A government can have a negative primary deficit (a primary surplus) while still running a fiscal deficit. Reason (R): Primary deficit equals fiscal deficit minus interest payments.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: if interest payments exceed the fiscal deficit, the primary balance is in surplus even though the government is still borrowing.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-72", "question": "Arrange in time order: 1. Minimum Needs Programme begins 2. Twenty Point Programme launched 3. Start of the Plan Holiday 4. Rolling Plan introduced", "options": ["3-2-1-4", "3-1-2-4", "3-1-4-2", "1-3-2-4"], "answer": 1, "explanation": "Plan Holiday (1966), Minimum Needs Programme (1974, Fifth Plan), Twenty Point Programme (1975), Rolling Plan (1978).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-73", "question": "How many of these statements about tax devolution under the Fifteenth Finance Commission are correct? I. It fixed the States' share of the divisible pool at 41% for 2021–26. II. Cesses and surcharges are outside the divisible pool. III. ‘Demographic performance’ was one of its criteria for sharing among States. IV. The share was cut from 42% partly because Jammu and Kashmir had become a Union Territory.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The 1 percentage point reduction roughly matched the share that would have gone to Jammu and Kashmir as a State.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-74", "question": "Match the type of tax with its description: A. Progressive B. Proportional C. Regressive D. Degressive — 1. The rate rises with income, but at a slower pace beyond a point 2. Takes a larger share of a poor person's income than a rich person's 3. The same rate at every level of income 4. The rate rises as income rises", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1"], "answer": 0, "explanation": "A progressive tax's rate rises with income, a proportional tax has one rate, a regressive tax weighs more on the poor, and a degressive tax is progressive only up to a point.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-75", "question": "Revenue receipts are ₹25 lakh crore, revenue expenditure ₹30 lakh crore, capital expenditure ₹10 lakh crore and non-debt capital receipts ₹2 lakh crore. Roughly what share of the government's borrowing goes to meet the revenue deficit?", "options": ["25%", "38.5%", "50%", "61.5%"], "answer": 1, "explanation": "Revenue deficit = 30 − 25 = 5. Fiscal deficit = (30 + 10) − (25 + 2) = 13. Share = 5 ÷ 13 ≈ 38.5%, meaning over a third of borrowing funds current spending rather than assets.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-76", "question": "How many of these statements about the Government of India's funds are correct? I. The Contingency Fund of India was created by a law of Parliament under Article 267. II. Money can be withdrawn from the Public Account without an appropriation by Parliament. III. All revenues, loans raised and loan repayments received by the Union go into the Consolidated Fund. IV. Charged expenditure can be discussed in Parliament but is not put to the vote.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct (Articles 267, 266(2), 266(1) and 113(1)).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-77", "question": "Assertion (A): The Rajya Sabha does not vote on the demands for grants. Reason (R): Article 113 provides that estimates of expenditure not charged on the Consolidated Fund are submitted to the Lok Sabha in the form of demands for grants.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A. The Rajya Sabha may discuss the Budget but has no power to vote on the demands.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-78", "question": "Which of these is NOT a revenue receipt of the Union Government?", "options": ["Dividends from public sector enterprises", "Interest received on loans given to States", "Recovery of loans given to States", "Corporation tax"], "answer": 2, "explanation": "Recovery of loans reduces the government's assets, so it is a non-debt capital receipt. Interest and dividends are non-tax revenue, and corporation tax is tax revenue.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-79", "question": "Match the committee or formula with its subject: A. Mahalanobis Committee (1960) B. Gadgil formula (1969) C. Lakdawala Expert Group (1993) D. Tendulkar Committee (2009) — 1. A new poverty line based on a wider consumption basket 2. Estimating poverty using State-specific price indices 3. Sharing central plan assistance among States 4. Distribution of income and levels of living", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "The Mahalanobis Committee studied income distribution, the Gadgil formula allocated central plan assistance from the Fourth Plan, Lakdawala used State-specific poverty lines, and Tendulkar revised the poverty line in 2009.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-80", "question": "Assertion (A): Raising indirect taxes tends to make the tax system more regressive. Reason (R): Indirect taxes are paid at the same rate on goods and services whatever the buyer's income.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: since the poor spend a larger share of their income on taxed consumption, a uniform indirect tax takes a larger share of their income.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-81", "question": "A government wants a fiscal deficit of 4.5% of GDP. Expected GDP is ₹320 lakh crore, revenue receipts ₹34 lakh crore and non-debt capital receipts ₹1 lakh crore. What is the most it can spend in total?", "options": ["₹48.4 lakh crore", "₹49.4 lakh crore", "₹50.4 lakh crore", "₹14.4 lakh crore"], "answer": 1, "explanation": "Allowed fiscal deficit = 4.5% × 320 = ₹14.4 lakh crore. Total expenditure = fiscal deficit + revenue receipts + non-debt capital receipts = 14.4 + 34 + 1 = ₹49.4 lakh crore.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-82", "question": "Arrange in time order: 1. FRBM Act passed 2. GST introduced 3. Gender Budget Statement first presented 4. Planning Commission set up", "options": ["1-4-3-2", "4-3-1-2", "4-1-2-3", "4-1-3-2"], "answer": 3, "explanation": "Planning Commission (1950), FRBM Act (2003), first Gender Budget Statement (2005–06), GST (2017).", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eco-planning-budget-83", "question": "Assertion (A): Raising more money through market borrowings reduces the fiscal deficit. Reason (R): Market borrowings are capital receipts of the government.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: borrowings are the very thing the fiscal deficit measures, so fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts) leaves them out. R is true: borrowings are debt-creating capital receipts.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-84", "question": "How many of these are classified as revenue expenditure in the Union Budget? I. Grants to States, even when used to create capital assets II. Interest payments on loans III. Defence capital outlay IV. Salaries of government employees", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are revenue expenditure: grants create no asset for the Union, and interest and salaries are current spending. Defence capital outlay is capital expenditure.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "eco-planning-budget-85", "question": "Assertion (A): Money advanced from the Contingency Fund of India for unforeseen expenditure is later made good from the Consolidated Fund once Parliament authorises the spending. Reason (R): Article 267 itself fixes the corpus of the Contingency Fund at ₹500 crore.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true: the Fund is recouped after Parliament approves the expenditure through a supplementary or excess grant. R is false: Article 267 only lets Parliament create the Fund by law; its corpus is set by that law and has been raised over time, to ₹30,000 crore in 2021.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-86", "question": "A budget in which the government's expenditure is greater than its receipts is called a:", "options": ["Surplus budget", "Balanced budget", "Deficit budget", "Zero-based budget"], "answer": 2, "explanation": "When spending exceeds receipts the gap must be met by borrowing or drawing on reserves, giving a deficit budget. A surplus budget has receipts above spending.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-planning-budget-87", "question": "Money spent by the government on building roads, bridges and dams is classified as:", "options": ["Capital expenditure", "Revenue expenditure", "Transfer payment", "Interest payment"], "answer": 0, "explanation": "Capital expenditure creates assets or reduces liabilities. Salaries, subsidies and interest, which create no assets, are revenue expenditure.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-planning-budget-88", "question": "A “vote on account” passed by the Lok Sabha allows the government to:", "options": ["Raise new taxes without a Finance Bill", "Withdraw money from the Consolidated Fund for part of the year until the full budget is passed", "Spend money from the Contingency Fund without approval", "Borrow abroad without limit"], "answer": 1, "explanation": "Under Article 116, a vote on account grants funds in advance, usually for a few months, so government can keep running while the full demands for grants are discussed.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "eco-planning-budget-89", "question": "In zero-based budgeting:", "options": ["The budget always shows zero deficit", "Spending is fixed at last year's level plus inflation", "Only capital expenditure is allowed", "Every item of spending must be justified afresh each year, without assuming last year's allocation"], "answer": 3, "explanation": "Zero-based budgeting starts each programme from zero, so it must prove its need. Incremental budgeting, by contrast, simply adds to the previous year's figure.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-planning-budget-90", "question": "Money the government receives from selling part of its shares in public sector companies is a:", "options": ["Revenue receipt", "Non-debt capital receipt", "Debt-creating capital receipt", "Tax receipt"], "answer": 1, "explanation": "Disinvestment reduces the government's assets and creates no repayment obligation, so it is a non-debt capital receipt, like recovery of loans.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-planning-budget-91", "question": "During a recession, a counter-cyclical fiscal policy would typically involve:", "options": ["Raising taxes and cutting spending", "Raising the repo rate", "Higher government spending and/or lower taxes", "Selling foreign exchange reserves"], "answer": 2, "explanation": "Fiscal policy leans against the cycle: it boosts demand in a slump and cools it in a boom. Changing the repo rate is monetary policy, decided by the RBI's MPC.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-planning-budget-92", "question": "In the Finance Commission's work, “horizontal devolution” refers to:", "options": ["The share of central taxes going to the states as a whole", "Grants to panchayats only", "Borrowing limits of states", "The distribution of the states' share among the individual states"], "answer": 3, "explanation": "Vertical devolution fixes how much of the divisible pool goes to all states together; horizontal devolution divides that share among states using criteria such as population, area and income distance.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-93", "question": "Which of the following is NOT part of the divisible pool of central taxes shared with the states?", "options": ["Cesses and surcharges levied by the Union", "Corporation tax", "Personal income tax", "Central GST"], "answer": 0, "explanation": "Under Article 270, cesses and surcharges stay with the Union, which is why states object when their share of central revenue rises. Corporation tax, income tax and CGST are shareable.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-94", "question": "Statutory grants-in-aid to states in need of assistance, made on the recommendation of the Finance Commission, are provided under:", "options": ["Article 282", "Article 275", "Article 360", "Article 112"], "answer": 1, "explanation": "Article 275 grants are charged on the Consolidated Fund and follow Finance Commission advice. Article 282 allows discretionary grants for any public purpose.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-95", "question": "The Public Accounts Committee of Parliament mainly examines:", "options": ["The budget estimates before they are voted", "Bills on taxation", "The CAG's audit reports on the government's accounts", "Appointments to public sector companies"], "answer": 2, "explanation": "The PAC scrutinises how money already spent was used, based on the CAG's reports; by convention since 1967 its chairperson comes from the opposition. Budget estimates go to the Estimates Committee.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-96", "question": "All members of which financial committee of Parliament are drawn from the Lok Sabha alone?", "options": ["Estimates Committee", "Public Accounts Committee", "Committee on Public Undertakings", "Business Advisory Committee of the Rajya Sabha"], "answer": 0, "explanation": "The Estimates Committee has 30 members, all from the Lok Sabha. The PAC and the Committee on Public Undertakings include members of the Rajya Sabha too.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-97", "question": "In budget procedure, the “guillotine” refers to:", "options": ["Cutting a ministry's budget by a token ₹100", "Rejecting the Finance Bill", "Transferring funds from one head to another", "Putting all remaining demands for grants to vote together on the last allotted day, without discussion"], "answer": 3, "explanation": "Because time is limited, the Speaker applies the guillotine so that demands not yet discussed are voted together. The ₹100 reduction is a token cut motion.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-98", "question": "Which of the following is NOT a statement laid before Parliament under the FRBM framework?", "options": ["Medium-term Fiscal Policy Statement", "Fiscal Policy Strategy Statement", "Monetary Policy Statement", "Macro-economic Framework Statement"], "answer": 2, "explanation": "The FRBM Act requires fiscal statements from the government alongside the budget. Monetary policy statements are issued by the RBI and its Monetary Policy Committee, not under the FRBM Act.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-planning-budget-99", "question": "How many of these statements are correct? I. No money can be withdrawn from the Consolidated Fund of India except under an appropriation made by law. II. No amendment can be moved to an Appropriation Bill that would change the amount of expenditure charged on the Consolidated Fund. III. The Finance Bill contains the government's tax proposals. IV. The Rajya Sabha can reject the Appropriation Bill.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Articles 114 and 266). The Appropriation Bill is a Money Bill, so the Rajya Sabha can only make recommendations within 14 days and cannot reject it; IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-planning-budget-100", "question": "Match the fiscal term with its meaning. A. Pump priming  B. Fiscal consolidation  C. Crowding out  D. Fiscal drag; 1. Rising nominal incomes push taxpayers into higher brackets, raising tax take and dampening demand  2. Government borrowing raises interest rates and squeezes private investment  3. Steadily reducing deficits and debt  4. Government spending to restart a slack economy", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1"], "answer": 0, "explanation": "Pump priming injects demand; consolidation is the FRBM-style path of lower deficits; crowding out is the cost of heavy borrowing; fiscal drag is an automatic tightening as incomes rise.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-planning-budget-101", "question": "Assertion (A): The fiscal deficit can be reduced without cutting expenditure by raising more through disinvestment. Reason (R): Disinvestment proceeds are non-debt capital receipts, which are subtracted along with revenue receipts from total expenditure to obtain the fiscal deficit.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts). More disinvestment shrinks the gap that must be borrowed, though critics call it selling the family silver to pay current bills.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-planning-budget-102", "question": "A government's debt is 80% of GDP (GDP = 100). Next year nominal GDP grows by 10% and the government borrows an amount equal to 5% of this year's GDP. What is the new debt-to-GDP ratio, approximately?", "options": ["85%", "77%", "80%", "75%"], "answer": 1, "explanation": "Debt becomes 80 + 5 = 85 and GDP becomes 110, so the ratio is 85/110 ≈ 77.3%. Nominal growth faster than debt growth lets the ratio fall even with a deficit.", "difficulty": "very-hard", "source": "UPSC Prelims · RBI Grade B"},
  {"id": "eco-planning-budget-103", "question": "How many of these statements about the Finance Commission are correct? I. It is constituted by the President every five years or earlier. II. It recommends how the net proceeds of shareable taxes are divided between the Union and the states. III. It suggests measures to augment states' Consolidated Funds to support panchayats and municipalities. IV. Its recommendations are binding on the Union Government.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct under Article 280. The Commission's recommendations are advisory, though by convention they are largely accepted, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-104", "question": "Arrange these themes or objectives in the order of the Five-Year Plans that adopted them: 1. Faster, more inclusive and sustainable growth  2. Growth with stability and progressive achievement of self-reliance  3. Growth with social justice and equality  4. Towards faster and more inclusive growth", "options": ["2-3-1-4", "3-2-4-1", "2-4-3-1", "2-3-4-1"], "answer": 3, "explanation": "The Fourth Plan (1969–74) sought growth with stability and self-reliance; the Ninth (1997–2002) growth with social justice and equality; the Eleventh (2007–12) faster and more inclusive growth; the Twelfth (2012–17) added “sustainable”.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "eco-planning-budget-105", "question": "Assertion (A): A high revenue deficit is considered a sign of poor fiscal health. Reason (R): It means the government is borrowing to meet day-to-day expenses that do not create assets to service future debt.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Borrowing to pay salaries, subsidies and interest leaves future taxpayers with debt but no matching assets or income, which is why the FRBM framework targets eliminating the revenue deficit.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-planning-budget-106", "question": "How many of these statements about the division of taxing powers are correct? I. Corporation tax is levied and collected by the Union but shared with the states. II. Stamp duties on bills of exchange are levied by the Union but collected and kept by the states. III. Tax on agricultural income can be levied only by the states. IV. The Union can levy tax on the sale of alcoholic liquor for human consumption.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II (Article 268) and III are correct. Liquor for human consumption is outside GST and taxed by the states (State List), so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"eco-planning-budget-107","question":"In a simple closed economy with a marginal propensity to consume of 0.75, the government raises its spending by ₹1,000 crore and also raises lump-sum taxes by ₹1,000 crore. Equilibrium income will rise by about:","options":["Zero, since the extra taxes cancel the extra spending","₹1,000 crore","₹4,000 crore","₹3,000 crore"],"answer":1,"explanation":"The spending multiplier is 1/(1 − 0.75) = 4 (+₹4,000 crore) and the tax multiplier −0.75/0.25 = −3 (−₹3,000 crore), a net rise of ₹1,000 crore: the balanced-budget multiplier is 1.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-108","question":"In a simple closed economy with a marginal propensity to consume of 0.8, a ₹100 crore cut in lump-sum taxes raises equilibrium income by about:","options":["₹500 crore","₹100 crore","₹400 crore","₹80 crore"],"answer":2,"explanation":"The tax multiplier is MPC/(1 − MPC) = 0.8/0.2 = 4, so income rises by ₹400 crore. It is smaller than the spending multiplier of 5 because households save part of any tax cut before it is spent.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-109","question":"Which of the following works as an 'automatic stabiliser' of the economy?","options":["A one-time stimulus package announced in the budget","An increase in the repo rate","A fixed allocation for defence capital spending","A progressive income tax, whose collections fall more than proportionately in a recession"],"answer":3,"explanation":"Automatic stabilisers cushion the cycle without fresh decisions: falling incomes cut tax payments sharply and welfare payments rise. A stimulus package is discretionary fiscal policy, and the repo rate is a monetary tool.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-110","question":"A new excise duty is collected from manufacturers, but they raise their prices so that buyers bear most of it. In public-finance terms:","options":["the impact of the tax is on manufacturers, while its incidence falls mainly on consumers","the impact is on consumers, while the incidence falls on manufacturers","it becomes a direct tax because manufacturers pay it","both its impact and its incidence fall on the government"],"answer":0,"explanation":"Impact is on whoever first pays the tax to the government; incidence is on whoever finally bears the burden. Indirect taxes are those whose burden can be shifted, which is exactly what happened here.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-111","question":"Which statement correctly distinguishes tax buoyancy from tax elasticity?","options":["Buoyancy measures the response of tax revenue to GDP including the effect of discretionary changes in tax rates and base, while elasticity excludes such discretionary changes","Elasticity includes discretionary changes in rates, while buoyancy excludes them","The two terms mean exactly the same thing","A buoyancy above 1 means that tax revenue is growing more slowly than GDP"],"answer":0,"explanation":"Elasticity captures the built-in response of the tax system to income growth; buoyancy also reflects new taxes, rate changes and better compliance. A buoyancy above 1 means revenue grows faster than GDP.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-112","question":"In the Harrod–Domar model, if the investment (savings) rate is 30% of GDP and the incremental capital–output ratio (ICOR) is 5, the growth rate of GDP is about:","options":["6%","16.7%","25%","1.5%"],"answer":0,"explanation":"Growth = savings rate ÷ ICOR = 30 ÷ 5 = 6%. A lower ICOR, i.e. more efficient use of capital, gives faster growth for the same investment; dividing ICOR by the rate (16.7%) inverts the formula.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-113","question":"Consider the following statements: I. No money can be withdrawn from the Consolidated Fund of India except under an appropriation made by law. II. No amendment may be proposed to an Appropriation Bill in either House that would vary the amount or change the destination of any grant made. III. The Appropriation Bill covers both the grants voted by the Lok Sabha and the expenditure charged on the Consolidated Fund. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":3,"explanation":"All three follow Articles 114 and 266. Charged expenditure is not voted on, but it is still included in the Appropriation Bill so that withdrawals have legal authority.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-114","question":"'Off-budget borrowing' by a government refers to:","options":["borrowing authorised through a vote on account","loans given by the Union to the States","borrowing by public bodies, such as the FCI from the National Small Savings Fund, to meet spending that would otherwise appear in the budget, so it does not show up in the fiscal deficit","external commercial borrowing by private companies"],"answer":2,"explanation":"Shifting spending to agencies that borrow on their own books flatters the headline deficit while the liability ultimately rests with the government; this is why such borrowings are now disclosed separately in budget documents.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-115","question":"The 'structural' (cyclically adjusted) budget deficit is the deficit that would occur:","options":["if only capital expenditure were counted","if the economy were operating at its potential output, after removing the effect of the business cycle on revenue and spending","if interest payments were excluded","after adding off-budget borrowings to the fiscal deficit"],"answer":1,"explanation":"In a slump revenues fall and some spending rises automatically, enlarging the actual deficit; the structural deficit strips this out to show the underlying fiscal stance. Excluding interest gives the primary deficit instead.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-116","question":"An 'inverted duty structure' under GST arises when:","options":["the tax rate on the output is higher than on the inputs","imported goods are taxed at a lower rate than exported goods","all goods are taxed at the same rate","the tax rate on inputs is higher than the rate on the final product, so input tax credit accumulates unused"],"answer":3,"explanation":"If inputs carry, say, 18% and the product 5%, the credit cannot be fully set off, blocking working capital; refunds of such accumulated credit are allowed in specified cases.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-117","question":"In Indian fiscal federalism, 'vertical fiscal imbalance' refers to:","options":["differences in revenue-raising capacity among the States","the gap between revenue and capital expenditure","the mismatch whereby the Union raises a larger share of revenue while the States bear a larger share of expenditure responsibilities","the imbalance between direct and indirect taxes"],"answer":2,"explanation":"Finance Commission tax devolution corrects this vertical gap; differences among States, the horizontal imbalance, are handled through the distribution formula and grants.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-118","question":"Grants that the Union or a State may make for any public purpose, even one outside its own legislative competence, are provided for under:","options":["Article 275","Article 282","Article 280","Article 293"],"answer":1,"explanation":"Article 282 discretionary grants have funded many centrally sponsored schemes. Article 275 covers statutory grants-in-aid on Finance Commission advice, Article 280 the Finance Commission itself and Article 293 borrowing by States.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-119","question":"A tax of ₹2 on every litre of a fuel, regardless of its price, is an example of:","options":["an ad valorem duty","a direct tax","a specific duty","a progressive tax"],"answer":2,"explanation":"A specific duty is a fixed amount per unit; an ad valorem duty is a percentage of value, so its yield rises automatically with prices while a specific duty's does not.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-planning-budget-120","question":"According to 'Ricardian equivalence', a debt-financed tax cut today has little effect on consumption because:","options":["government spending falls automatically","interest rates fall to zero","the multiplier becomes very large","households expect higher future taxes to repay the debt, so they save the tax cut"],"answer":3,"explanation":"Forward-looking households treat government borrowing as deferred taxation, so total private saving rises to offset public dissaving. In practice, liquidity-constrained households weaken this result.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-121","question":"The 'golden rule' of fiscal policy says that, over the economic cycle, a government should:","options":["borrow only to finance investment, meeting current spending from current revenue","never borrow at all","borrow only to pay salaries and subsidies","keep its total debt fixed in rupee terms"],"answer":0,"explanation":"Borrowing for assets that raise future output can pay for itself, while borrowing for consumption burdens future taxpayers; in Indian budget terms the rule amounts to eliminating the revenue deficit.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-122","question":"If a government's primary deficit is zero in a year, its fiscal deficit equals its:","options":["revenue deficit","interest payments","capital expenditure","total expenditure"],"answer":1,"explanation":"Primary deficit = fiscal deficit − interest payments, so a zero primary deficit means the government borrows only to pay interest on past debt.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-planning-budget-123","question":"A government’s debt is 60% of GDP. The nominal interest rate on its debt is 7% and nominal GDP grows at 11% a year. What primary balance keeps the debt-to-GDP ratio exactly constant?","options":["A primary surplus of about 2.2% of GDP","A primary deficit of about 2.2% of GDP","A primary deficit of about 2.4% of GDP","A primary surplus of about 2.4% of GDP"],"answer":1,"explanation":"The debt ratio is stable when the primary deficit equals d(g − r)/(1 + g) = 0.60 × 0.04 / 1.11 ≈ 2.16% of GDP. Because g > r, the government can run a primary deficit; 2.4% forgets to divide by (1 + g).","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-124","question":"Under the FRBM Act as amended in 2018, when the Centre invokes the ‘escape clause’ on grounds such as war, a national calamity or a collapse of agriculture, the fiscal deficit may exceed the target by at most:","options":["0.25% of GDP","1% of GDP","0.5% of GDP","1.5% of GDP"],"answer":2,"explanation":"The amended Act allows a deviation of up to 0.5% of GDP in a year on the specified grounds, and the Finance Minister must explain the reasons to Parliament. 0.25% is the minimum deficit cut required under the ‘buoyancy’ clause.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-125","question":"In the GST Council a decision needs at least three-fourths of the weighted votes of members present and voting; the Centre’s vote counts for one-third and all the States together for two-thirds. If every State is present and voting and the Centre supports a proposal, what minimum share of the States must also support it?","options":["75%","66.7%","50%","62.5%"],"answer":3,"explanation":"Needed: 1/3 + f × 2/3 ≥ 3/4, so f ≥ (5/12)/(2/3) = 5/8 = 62.5%. The trap is to apply 75% to the States alone, forgetting the Centre’s one-third already counts.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-126","question":"A rural roads scheme is to be judged by the rise in villages’ all-weather access to markets and health centres rather than by the kilometres of road laid. Which budgeting approach does this reflect?","options":["Line-item budgeting","Performance budgeting","Outcome budgeting","Zero-based budgeting"],"answer":2,"explanation":"Outcome budgeting measures the results that spending achieves for people; performance budgeting tracks activities and physical outputs such as kilometres built. Zero-based budgeting is about justifying each item afresh.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-127","question":"Match the Article with its GST provision: A. Article 246A  B. Article 269A  C. Article 279A  D. Article 366(12A); 1. Defines ‘goods and services tax’  2. Constitutes the GST Council  3. Special power of Parliament and State legislatures to make laws on GST  4. Levy and collection of GST on inter-State supplies by the Union","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Article 246A gives the concurrent power to legislate on GST (with inter-State supply reserved for Parliament), 269A covers IGST on inter-State trade, 279A sets up the Council and 366(12A) defines GST. All came with the 101st Amendment, 2016.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-128","question":"Under the Provisional Collection of Taxes Act, 1931, tax changes declared in the Finance Bill take effect immediately, but they lapse if the Bill is not enacted within:","options":["14 days","60 days","90 days","75 days"],"answer":3,"explanation":"The Act lets declared provisions operate at once, to stop people dodging a new levy, but only for 75 days unless the Finance Bill becomes law earlier. 14 days is the Rajya Sabha’s limit on a Money Bill.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-129","question":"How many of these statements are correct? I. A Money Bill can be introduced only on the recommendation of the President. II. A Financial Bill under Article 117(1) can be introduced only in the Lok Sabha. III. A Financial Bill under Article 117(3), which merely involves expenditure from the Consolidated Fund, can be introduced in either House. IV. Like a Money Bill, a Financial Bill under Article 117(1) cannot be rejected by the Rajya Sabha.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Apart from the rules on introduction, an Article 117(1) Bill is treated as an ordinary Bill, so the Rajya Sabha can amend or reject it and a joint sitting is possible; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-130","question":"Which of the following is charged on the Consolidated Fund of India?","options":["Salaries of the judges of High Courts","Salary of the Attorney General of India","Pensions of the judges of High Courts","Salaries of the Union Cabinet ministers"],"answer":2,"explanation":"Article 112(3) charges the pensions of High Court judges on the Consolidated Fund of India, but their salaries are charged on the Consolidated Fund of the State. The Attorney General’s pay and ministers’ salaries are voted expenditure.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-131","question":"Assertion (A): Money can be paid out of the Public Account of India without an appropriation passed by Parliament. Reason (R): Sums in the Public Account, such as provident fund and small savings deposits, are held by the government as a banker and must be repaid to their owners.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Under Article 266(2), the Public Account holds money that is not the government’s own revenue; the government acts as a banker or trustee, so withdrawals need no appropriation law, unlike the Consolidated Fund.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-132","question":"A budget shows: revenue receipts ₹20 lakh crore; revenue expenditure ₹26 lakh crore, including interest payments of ₹7 lakh crore; capital expenditure ₹6 lakh crore; recovery of loans ₹1 lakh crore; disinvestment receipts ₹1 lakh crore. The fiscal deficit and primary deficit are:","options":["₹12 and ₹5 lakh crore","₹11 and ₹4 lakh crore","₹6 and −₹1 lakh crore","₹10 and ₹3 lakh crore"],"answer":3,"explanation":"Fiscal deficit = total expenditure 32 − (revenue receipts 20 + non-debt capital receipts 2) = 10; primary deficit = 10 − interest 7 = 3. Ignoring the non-debt receipts gives 12 and 5; ₹6 lakh crore is the revenue deficit.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-133","question":"Financing a deficit by creating new money is often called an ‘inflation tax’ mainly because:","options":["Rising prices push taxpayers into higher income-tax slabs and raise collections","Rising prices erode the real value of money people hold, shifting resources to the issuer","The central bank pays interest on the new money, which the government then taxes","Higher prices raise GST collections, since GST is charged as a share of value"],"answer":1,"explanation":"New money lets the government buy real resources, while inflation cuts the purchasing power of the cash already held by the public, acting like a tax on money balances. Bracket creep (fiscal drag) is a different effect.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-134","question":"In Musgrave’s three-fold classification of the functions of public finance, deliberately running a larger deficit during a slump to revive demand belongs to the:","options":["Allocation function","Distribution function","Stabilisation function","Regulation function"],"answer":2,"explanation":"Musgrave’s functions are allocation (providing goods the market under-supplies), distribution (adjusting income shares) and stabilisation (keeping output, employment and prices steady); counter-cyclical deficits serve stabilisation.","difficulty":"moderate","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-135","question":"An uncongested toll expressway, from which non-payers can be shut out but where one more car imposes no cost on other users, is an example of a:","options":["Club (toll) good","Pure public good","Common-pool resource","Pure private good"],"answer":0,"explanation":"It is excludable (tolls) but non-rival (while uncongested), which defines a club good. A pure public good is non-excludable as well; a common-pool resource is rival but non-excludable.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-136","question":"The ‘displacement effect’, under which public spending jumps during a crisis such as a war and does not fall back to its old level afterwards, is associated with:","options":["Adolph Wagner","Richard Musgrave","Hugh Dalton","Peacock and Wiseman"],"answer":3,"explanation":"Peacock and Wiseman argued that public spending rises in steps: crises raise the tax level people tolerate, and it stays higher later. Wagner’s law links a rising share of public spending to industrial growth in general.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-137","question":"Which of the following is NOT one of Adam Smith’s four canons of taxation?","options":["Certainty","Convenience","Economy","Elasticity"],"answer":3,"explanation":"Smith’s canons are equality, certainty, convenience and economy. Elasticity, productivity and simplicity were added by later writers such as Bastable.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-138","question":"Two taxpayers with the same income and circumstances paying the same amount of tax illustrates:","options":["Horizontal equity","Vertical equity","The benefit principle","Tax neutrality"],"answer":0,"explanation":"Horizontal equity means equals are treated equally; vertical equity means those with a greater ability to pay bear more. The benefit principle links tax to the benefit received from public services.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-139","question":"A per-unit tax is imposed on the sellers of a good whose demand is perfectly inelastic and whose supply curve slopes upward. The burden of the tax falls:","options":["Entirely on the sellers, since they pay it to the treasury","Entirely on the buyers, as the price rises by the full tax","Equally on buyers and sellers, whatever the elasticities","Mostly on the sellers, as the quantity sold falls sharply"],"answer":1,"explanation":"Incidence depends on elasticities, not on who hands the tax over. With perfectly inelastic demand, quantity does not change and the price rises by the whole tax, so buyers bear all of it.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-140","question":"With straight-line demand and supply curves, if a per-unit tax on a good is doubled, the deadweight loss from the tax:","options":["Also roughly doubles in size","Rises by about one and a half times","Becomes about four times as large","Stays about the same, as only prices change"],"answer":2,"explanation":"Deadweight loss is a triangle of ½ × tax × fall in quantity, and the fall in quantity is itself proportional to the tax, so the loss rises with the square of the tax rate. This is why broad bases with low rates are preferred.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-141","question":"Which pairing of a Five-Year Plan with its stated focus is correct?","options":["Fifth Plan – Growth with social justice and equality","Seventh Plan – Food, work and productivity","Ninth Plan – Removal of poverty (Garibi Hatao)","Third Plan – Faster and more inclusive growth"],"answer":1,"explanation":"The Seventh Plan (1985–90) stressed food, work and productivity. Garibi Hatao belongs to the Fifth Plan, growth with social justice and equality to the Ninth, and faster and more inclusive growth to the Eleventh.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-142","question":"The Mahalanobis model behind the Second Five-Year Plan argued that, in a closed economy, the long-run rate of growth depends mainly on:","options":["The share of investment going to the capital-goods sector","The share of investment going to agriculture and irrigation","The growth of export earnings to pay for imported machinery","The inflow of foreign aid to fill the domestic savings gap"],"answer":0,"explanation":"Assuming a closed economy, Mahalanobis held that a larger share of investment in machine-making (capital goods) raises future investment capacity and growth, which is why the Second Plan favoured heavy industry. The aid argument is the two-gap model.","difficulty":"moderate","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-143","question":"A key functional difference between NITI Aayog and the former Planning Commission is that NITI Aayog:","options":["Is a statutory body, while the Planning Commission was set up by a resolution","Is chaired by the Finance Minister rather than by the Prime Minister","Prepares Five-Year Plans that must be approved by the National Development Council","Has no power to allocate plan funds to central ministries and the States"],"answer":3,"explanation":"The Planning Commission decided plan allocations to ministries and States; NITI Aayog is an advisory think tank without fund-allocation powers. Like its predecessor it was created by a Cabinet resolution and is chaired by the PM.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-144","question":"The duty of the Finance Commission to recommend measures to augment a State’s Consolidated Fund so as to supplement the resources of Panchayats and Municipalities was added by:","options":["The 42nd Amendment of 1976","The 80th Amendment of 2000","The 101st Amendment of 2016","The 73rd and 74th Amendments"],"answer":3,"explanation":"The 73rd and 74th Amendments (1992) inserted Article 280(3)(bb) and (c), on the basis of State Finance Commission reports. The 80th Amendment changed tax sharing to a divisible pool; the 101st brought GST.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-145","question":"A State Finance Commission is constituted:","options":["By the President every five years, under Article 280","By the Governor every five years, under Article 243-I","By the Union Finance Commission, under Article 243Y","By the State legislature every three years, under Article 243-I"],"answer":1,"explanation":"Article 243-I requires the Governor to constitute a Finance Commission every five years to review the finances of Panchayats; Article 243Y extends its remit to Municipalities. Article 280 covers the Union Finance Commission.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-146","question":"A State still owes part of a loan made to it by the Government of India and wants to raise a fresh loan in the market. Under Article 293 it:","options":["May borrow freely within India, subject only to RBI guidelines","Needs a resolution passed by both Houses of Parliament","Can borrow only from the RBI through ways and means advances","Needs the consent of the Government of India for the loan"],"answer":3,"explanation":"Article 293(3) says a State may not raise a loan without the Union’s consent while any part of a Union loan to it is outstanding; the Union may attach conditions. States can borrow only within India.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-147","question":"Under Article 276, the total of taxes on professions, trades, callings and employments that any one person can be made to pay to a State or local body in a year cannot exceed:","options":["₹2,500","₹250","₹5,000","₹25,000"],"answer":0,"explanation":"The ceiling of ₹250 was raised to ₹2,500 by the 60th Amendment (1988), and it remains in the Constitution. Because of this cap, professional tax is a minor source of State revenue.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-148","question":"Under Article 268, stamp duties on bills of exchange, cheques and promissory notes mentioned in the Union List are:","options":["Levied and collected by the States under their own laws","Levied by the Union but collected and kept by the States","Levied and collected by the Union and assigned wholly to the States","Levied and collected by the Union and shared through the divisible pool"],"answer":1,"explanation":"Article 268 covers duties that the Union imposes but that the States collect and appropriate. Article 269 covers taxes the Union both levies and collects but assigns to the States; Article 270 covers the shared divisible pool.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-149","question":"In a closed economy the marginal propensity to consume out of disposable income is 0.8 and income tax is a flat 25% of income. If government spending rises by ₹100 crore, equilibrium income rises by:","options":["₹500 crore","₹400 crore","₹250 crore","₹200 crore"],"answer":2,"explanation":"Multiplier = 1/[1 − c(1 − t)] = 1/(1 − 0.8 × 0.75) = 1/0.4 = 2.5, so income rises by ₹250 crore. ₹500 crore ignores the tax leakage; ₹400 crore uses the tax multiplier c/(1 − c).","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-150","question":"‘Fiscal dominance’ describes a situation in which:","options":["The finance ministry, not the central bank, legally fixes the policy repo rate each quarter","Fiscal policy beats monetary policy in a liquidity trap, so the treasury takes the lead","Persistent budget surpluses absorb private saving and push market interest rates down","Heavy deficits and debt press the central bank to keep rates low or fund the government"],"answer":3,"explanation":"Under fiscal dominance the government’s financing needs constrain monetary policy, forcing low rates or monetisation and weakening the central bank’s control of inflation. That is why an independent inflation-targeting framework is paired with fiscal rules.","difficulty":"hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-151","question":"In an open economy, private saving is 25% of GDP, private investment 28% of GDP and the government’s budget deficit 6% of GDP. Using the identity (S − I) + (T − G) = (X − M), the current account balance is:","options":["A deficit of 9% of GDP","A deficit of 3% of GDP","A surplus of 3% of GDP","A deficit of 6% of GDP"],"answer":0,"explanation":"(S − I) = −3 and (T − G) = −6, so X − M = −9% of GDP. This ‘twin deficits’ link shows that a larger fiscal deficit, unless matched by higher private saving, widens the current account deficit.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-152","question":"A small trader opts for the GST composition scheme. Which consequence follows?","options":["He pays tax at a low flat rate on turnover but cannot claim input tax credit or charge GST to buyers","He pays no GST at all but can still pass input tax credit on to his business buyers","He pays only IGST on all sales, while CGST and SGST on his supplies are fully waived","He claims input tax credit as usual but pays tax at a flat rate on profit, not on turnover"],"answer":0,"explanation":"The composition scheme trades simplicity for credit: tax is paid at a low rate on turnover, input tax credit is not available, and the dealer cannot collect GST from customers, so his buyers get no credit either.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-153","question":"During a Financial Emergency proclaimed under Article 360, the President may:","options":["Levy taxes on State List subjects without any law of Parliament","Transfer the balance of a State’s Consolidated Fund to the Union","Direct a cut in the salaries of Supreme Court and High Court judges","Spend from the Consolidated Fund of India without an appropriation law"],"answer":2,"explanation":"Article 360 lets the President direct reductions in the salaries of Union and State employees, including Supreme Court and High Court judges, and require State Money Bills to be reserved for consideration. It does not suspend the need for laws to tax or spend.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-154","question":"How many of these statements are correct? I. The distinction between Plan and Non-Plan expenditure was dropped from the Union Budget of 2017–18. II. The Union Government keeps its accounts on a cash basis. III. The Receipt Budget shows recoveries of loans as revenue receipts. IV. Excess grants are voted by the Lok Sabha before the extra money is spent, on the advice of the Public Accounts Committee.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Recoveries of loans are non-debt capital receipts, and excess grants are voted only after the money has been spent and the PAC has examined the excess, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-155","question":"The National Planning Committee set up by the Indian National Congress in 1938 was chaired by:","options":["Jawaharlal Nehru","Subhas Chandra Bose","M. Visvesvaraya","P. C. Mahalanobis"],"answer":0,"explanation":"The committee was set up in 1938 during Subhas Chandra Bose’s term as Congress President, but Jawaharlal Nehru chaired it. Visvesvaraya had earlier written Planned Economy for India (1934).","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-156","question":"‘Planned Economy for India’ (1934), one of the earliest blueprints for economic planning in the country, was written by:","options":["Shriman Narayan","M. N. Roy","M. Visvesvaraya","J. R. D. Tata"],"answer":2,"explanation":"Engineer-statesman M. Visvesvaraya proposed doubling national income in ten years through industrialisation. Shriman Narayan wrote the Gandhian Plan, M. N. Roy the People’s Plan, and Tata was among the Bombay Plan authors.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-157","question":"How many of these statements about short-term government paper are correct? I. Treasury bills are issued at a discount and redeemed at face value. II. The Government of India issues Treasury bills of 91, 182 and 364 days. III. State governments raise short-term funds by issuing their own Treasury bills. IV. Cash Management Bills, of less than 91 days, meet temporary mismatches in the Centre’s cash flow.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Only the Centre issues Treasury bills; States borrow through State Development Loans and meet short-term gaps with ways and means advances from the RBI, so III is wrong.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-158","question":"A 91-day Treasury bill with a face value of ₹100 is issued at ₹98.50. Its annualised yield on a 365-day basis is about:","options":["6.00%","6.02%","6.11%","1.52%"],"answer":2,"explanation":"Yield = (100 − 98.5)/98.5 × 365/91 × 100 ≈ 6.11%. Dividing the discount by face value instead of price gives 6.02%; simply multiplying 1.5% by four gives 6.00%; 1.52% is not annualised.","difficulty":"hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-159","question":"Ways and Means Advances (WMA) from the RBI to the Government of India are meant to:","options":["Finance the government’s fiscal deficit on a permanent basis","Bridge temporary mismatches between the government’s receipts and payments","Refinance the government’s maturing dated securities at below-market rates","Fund the capital of public sector banks during a financial crisis"],"answer":1,"explanation":"WMA are short-term advances, within limits agreed with the RBI, that cover timing gaps in cash flow; use beyond the limit becomes an overdraft. They replaced the ad hoc Treasury bills that had monetised deficits automatically.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-160","question":"Assertion (A): Since April 2006 the RBI has generally not subscribed to the primary issues of the Central Government’s securities. Reason (R): The FRBM Act also bars the RBI from buying Central Government securities in the secondary market through open market operations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"The FRBM Act barred RBI subscription to primary issues from 1 April 2006, except on specified grounds, but expressly allowed it to trade G-secs in the secondary market, which is how OMOs work. So A is true and R is false.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-161","question":"Collections under small savings schemes such as the Public Provident Fund and National Savings Certificates are credited to the National Small Savings Fund, which is part of the:","options":["Consolidated Fund of India","Contingency Fund of India","Public Account of India","Reserve Bank’s balance sheet"],"answer":2,"explanation":"The NSSF, set up in 1999, sits in the Public Account because the deposits belong to savers and must be repaid. Its money is lent mainly to the Centre through special securities, one source of financing the fiscal deficit.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-162","question":"Which criterion used by the Fifteenth Finance Commission for sharing taxes among the States was meant to reward States that had brought down their fertility rates?","options":["Demographic performance","Income distance","Forest and ecology","Area"],"answer":0,"explanation":"Because the 2011 population was used, the Commission added ‘demographic performance’ so that States that had controlled population growth were not penalised. Income distance favours poorer States, and forest cover rewards ecological services.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-163","question":"Under the ‘income distance’ criterion used by recent Finance Commissions for horizontal devolution, a State gets a larger share when:","options":["Its per capita income is further below that of the highest-income States","Its total income has grown faster than the national average in recent years","Its own tax revenue is a larger share of its gross State domestic product","Its per capita income is closer to that of the highest-income States"],"answer":0,"explanation":"Income distance measures how far a State’s per capita income lies below a benchmark of the richest States; the greater the gap, the larger the share, so it is an equalising criterion. Tax effort is rewarded by a separate criterion.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-164","question":"Under the reverse charge mechanism in GST:","options":["The supplier pays the tax and later recovers it from the government as a refund","The recipient of the supply, rather than the supplier, is liable to pay the tax","The tax is collected only at the final retail stage instead of at each stage","The Centre pays the tax on behalf of small suppliers below the threshold"],"answer":1,"explanation":"Normally the supplier pays GST; for notified supplies, or purchases from certain unregistered persons, the liability shifts to the recipient, who may then claim input tax credit if eligible.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-165","question":"Exports are ‘zero-rated’ under GST. This means that the exporter:","options":["Pays no tax on the export and cannot claim credit for tax paid on inputs","Pays tax at a token rate of 0.1% and can claim credit for tax paid on inputs","Pays no tax on the export and can still claim or get a refund of input tax credit","Pays the full tax on the export but gets a refund once foreign payment arrives"],"answer":2,"explanation":"Zero-rating removes tax from the export and refunds the tax embedded in inputs, so exports leave free of domestic taxes. An exempt supply also bears no output tax, but its input tax credit is lost.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-166","question":"Assertion (A): A firm making only GST-exempt supplies often bears higher costs than a firm making zero-rated supplies. Reason (R): Input tax credit is not available on inputs used for exempt supplies, so the tax on inputs becomes part of the firm’s cost.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Neither firm charges output tax, but only the zero-rated supplier can recover the GST paid on inputs. For the exempt supplier that tax is stranded and raises costs, which is why ‘exempt’ is not the same as ‘tax-free’.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-167","question":"Under the GST rules, an e-way bill is generally required before moving goods whose consignment value exceeds:","options":["₹25,000","₹1 lakh","₹10 lakh","₹50,000"],"answer":3,"explanation":"The e-way bill, generated on the common portal, is needed for movement of goods worth more than ₹50,000 per consignment, with some State-specific variations for movement within a State.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-168","question":"The GST (Compensation to States) Act, 2017 worked out each State’s ‘protected revenue’ by assuming that its revenue from the subsumed taxes would grow every year by:","options":["10%","12%","14%","15%"],"answer":2,"explanation":"Revenue for the base year 2015–16 was projected to grow at 14% a year; any shortfall of actual GST revenue below this was paid from the compensation cess fund for five years.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-169","question":"Minimum Alternate Tax (MAT) is meant for companies that:","options":["Report large book profits but pay little normal tax because of exemptions and deductions","Make losses in their books and so would otherwise pay no tax at all on their turnover","Distribute dividends to shareholders out of profits that have not yet been taxed","Earn income abroad on which no tax has been paid to any foreign government"],"answer":0,"explanation":"MAT taxes a minimum share of book profit when tax under the normal provisions falls below it, stopping ‘zero-tax companies’ that show healthy profits to shareholders. Firms with book losses pay no MAT.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-170","question":"Which of these taxes is administered by the Central Board of Direct Taxes rather than by the Central Board of Indirect Taxes and Customs?","options":["Basic customs duty on imports","Central excise duty on petrol","Integrated GST on imports","Securities Transaction Tax"],"answer":3,"explanation":"Securities Transaction Tax, introduced in 2004 on deals in securities on recognised stock exchanges, is collected under the Finance Act and administered by the CBDT. Customs, excise and IGST fall under the CBIC.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-171","question":"After the Union Budget 2020–21 abolished the Dividend Distribution Tax, dividends from Indian companies are taxed:","options":["In the hands of the shareholders, at the rates that apply to them","Only in the hands of the company, at a flat rate on profits paid out","Neither in the company’s hands nor in the hands of shareholders","Only when shareholders sell their shares, as part of capital gains"],"answer":0,"explanation":"DDT was paid by companies on dividends declared; from 2020–21 the classical system returned, with dividends added to the shareholder’s income and taxed at his or her applicable rate, with tax deducted at source.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-172","question":"Under a hypothetical income tax, income up to ₹3 lakh is exempt, the next ₹3 lakh is taxed at 10% and income above ₹6 lakh at 20%. For a person earning ₹10 lakh, the average and marginal tax rates are:","options":["Average 20%, marginal 20%","Average 11%, marginal 20%","Average 11%, marginal 10%","Average 15%, marginal 20%"],"answer":1,"explanation":"Tax = 10% of 3 lakh + 20% of 4 lakh = ₹1.1 lakh, an average rate of 11%; the rate on the last rupee earned is 20%. Applying 20% to the whole income is the common slab-system mistake.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-173","question":"Which of the following is NOT a source of financing the Union Government’s fiscal deficit?","options":["Net market borrowings through dated securities","Securities issued against small savings","Net external assistance from multilateral bodies","Proceeds from disinvestment of PSU shares"],"answer":3,"explanation":"Disinvestment is a non-debt capital receipt that is counted before the deficit is struck, so it reduces the fiscal deficit rather than financing it. The deficit itself is financed by borrowing from the market, small savings, external sources and so on.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-174","question":"A government’s debt is 50% of GDP and its primary budget is exactly balanced. If the nominal interest rate on debt is 8% and nominal GDP grows by 10%, next year’s debt-to-GDP ratio will be about:","options":["49.0%","49.1%","51.0%","50.0%"],"answer":1,"explanation":"With no primary deficit, debt grows only by interest: 50 × 1.08 / 1.10 ≈ 49.09% of GDP. Subtracting the 2-point growth–interest gap from 50% straight away gives 49.0%, which ignores the division by (1 + g).","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-175","question":"Which of the following did NOT contribute to the ‘Plan Holiday’ of 1966–69?","options":["The war with Pakistan in 1965","Two successive droughts in the mid-1960s","The shortfall of the Third Plan’s targets","The first oil price shock of 1973"],"answer":3,"explanation":"War, drought, the Third Plan’s failure and the 1966 devaluation forced three Annual Plans before the Fourth Plan began in 1969. The oil shock came in 1973, during the Fourth Plan.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-176","question":"The first Five-Year Plan to adopt ‘monitorable targets’ for indicators such as poverty, literacy and infant mortality, in addition to a target for GDP growth, was the:","options":["Eighth Plan","Ninth Plan","Eleventh Plan","Tenth Plan"],"answer":3,"explanation":"The Tenth Plan (2002–07) recognised that growth alone was not enough and set monitorable targets for key social indicators. The Eleventh Plan later expanded the list of such targets.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-177","question":"Using the Harrod–Domar relation, if the incremental capital–output ratio is 4.5, by how many percentage points of GDP must the investment rate rise to lift growth from 6% to 8%?","options":["2 percentage points","4.5 percentage points","9 percentage points","8 percentage points"],"answer":2,"explanation":"Investment rate = growth × ICOR, so it must rise from 27% to 36% of GDP, a rise of 2 × 4.5 = 9 points. Answering 2 confuses the change in growth with the change in investment.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-178","question":"If a government’s revenue deficit is larger than its fiscal deficit, it follows that:","options":["Interest payments must exceed the primary deficit of that year","Non-debt capital receipts exceed capital spending and help fund revenue spending","Capital expenditure is being financed entirely out of fresh borrowing","The government must be running a surplus on its revenue account"],"answer":1,"explanation":"Fiscal deficit = revenue deficit + capital expenditure − non-debt capital receipts. If the fiscal deficit is smaller, non-debt receipts such as disinvestment exceed capital spending and are financing current spending, a weak fiscal sign.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-179","question":"Net fiscal deficit differs from gross fiscal deficit in that it:","options":["Deducts the government’s net lending to States and other bodies","Excludes the interest payments on past borrowing","Adds the borrowing done by public enterprises outside the budget","Counts only the part of borrowing financed by the RBI"],"answer":0,"explanation":"Net fiscal deficit = gross fiscal deficit − net lending (loans given minus recoveries), since loans create financial assets. Excluding interest gives the primary deficit; RBI financing is the monetised deficit.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-180","question":"Which of these is credited to the Public Account of India rather than to the Consolidated Fund of India?","options":["Proceeds of Treasury bills issued by the Centre","Provident fund deposits of government employees","Income tax collected by the Union","Recoveries of loans given to State governments"],"answer":1,"explanation":"Article 266(1) puts all revenue, all loans raised (including Treasury bills) and loan repayments into the Consolidated Fund. Provident fund deposits are held in trust and go to the Public Account under Article 266(2).","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-181","question":"Under Article 116, a ‘vote of credit’ is granted by the Lok Sabha when:","options":["The demand for money cannot be stated in detail because of its size or indefinite nature","Money already spent on a service exceeds the amount granted for that year","A new service not in the Budget needs only a token sum to begin","Money is needed for part of the year until the Budget is passed"],"answer":0,"explanation":"A vote of credit is like a blank cheque for an unexpected demand, such as during a war, whose details cannot be given. The other options describe an excess grant, a token grant and a vote on account.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-182","question":"Since 1993, between the general discussion on the Budget and the voting on demands, the demands for grants of ministries are examined in detail by:","options":["The Estimates Committee","The Public Accounts Committee","The Committee on Public Undertakings","The Department-related Standing Committees"],"answer":3,"explanation":"Department-related Standing Committees scrutinise each ministry’s demands during the Budget recess and report to Parliament. The PAC examines accounts after spending, and the Estimates Committee suggests economies.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-183","question":"The doctrine of ‘functional finance’, associated with Abba Lerner, holds that:","options":["The budget should be balanced every year to keep public finances sound","Taxes, spending and borrowing should be judged by their effects on employment and prices, not on budget balance","Public spending should be confined to defence, justice and essential public works","Government should borrow only to finance investment and never to meet current spending"],"answer":1,"explanation":"Lerner argued that fiscal tools exist to keep the economy at full employment without inflation, so deficits or surpluses are fine if they achieve that. Annual balance is ‘sound finance’, and borrowing only for investment is the golden rule.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-184","question":"Under Article 292, the Union Government may borrow on the security of the Consolidated Fund of India:","options":["Only with the prior approval of the Reserve Bank of India","Within the limits, if any, that Parliament fixes by law","Only within India and never from foreign lenders","Up to the limits that the Finance Commission recommends"],"answer":1,"explanation":"Article 292 lets the Union borrow within or outside India within limits Parliament may fix by law; States, under Article 293, can borrow only within India. Parliament has instead set deficit and debt targets through the FRBM Act.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-185","question":"Which of the following is still levied by the States outside GST?","options":["Entertainment tax by the State on cinema tickets","Value added tax on mobile phones","Luxury tax on hotel rooms","Electricity duty on power consumed"],"answer":3,"explanation":"Electricity is kept out of GST, so States continue to levy electricity duty. State entertainment tax, VAT on goods such as phones and luxury tax were all subsumed in GST in 2017.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-186","question":"States were induced to enact their own fiscal responsibility laws in the mid-2000s mainly because:","options":["The FRBM Act, 2003 directly applied its targets to every State","The GST Council required them as a condition for compensation","The RBI refused to manage the debt of States that lacked such laws","The Twelfth Finance Commission linked debt relief to passing such laws"],"answer":3,"explanation":"The Twelfth Finance Commission (2005–10) tied its debt consolidation and relief facility to States enacting fiscal responsibility legislation, and nearly all did. The Union FRBM Act binds only the Centre.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-187","question":"Under Article 279, the ‘net proceeds’ of a Union tax, which decide how much is shared with the States, are ascertained and certified by:","options":["The Finance Commission of India","The Comptroller and Auditor-General of India","The Secretary, Department of Revenue","The Controller General of Accounts"],"answer":1,"explanation":"Article 279 makes the CAG’s certificate of net proceeds (collections minus the cost of collection) final. The Finance Commission recommends the share, but does not certify the amount.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-188","question":"Under Article 289, the property and income of a State are exempt from Union taxation, but Parliament may by law tax:","options":["Income from a trade or business run by or for the State government","Agricultural income earned on farms that the State government owns and runs","Salaries that the State pays to members of its own civil services","Land and buildings the State uses for its ordinary government offices"],"answer":0,"explanation":"Article 289(2) lets the Union tax a State’s trading or business operations, unless Parliament declares a trade incidental to ordinary government functions. Ordinary government property and income stay exempt.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-189","question":"The qualifications of the members of the Finance Commission, and the way they are selected, are laid down by:","options":["Article 280 of the Constitution itself, in full detail","An order issued by the President after consulting the CAG","A law made by Parliament under Article 280(2)","Rules framed by NITI Aayog with the Finance Ministry’s approval"],"answer":2,"explanation":"Article 280(2) leaves these matters to Parliament, which passed the Finance Commission (Miscellaneous Provisions) Act, 1951. It requires, for example, that the chairman have experience in public affairs.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-190","question":"The idea of a ‘rolling plan’, adopted by the Janata government in 1978 with targets revised every year, is usually credited to:","options":["Gunnar Myrdal","P. C. Mahalanobis","D. R. Gadgil","Ragnar Nurkse"],"answer":0,"explanation":"Gunnar Myrdal advocated plans that are reviewed and extended each year instead of fixed five-year blocks. D. R. Gadgil, then Deputy Chairman of the Planning Commission, is known for the Gadgil formula.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-191","question":"The draft of the Fifth Five-Year Plan (1974–79), which stressed removal of poverty and self-reliance, was prepared under:","options":["D. P. Dhar","D. R. Gadgil","Gulzarilal Nanda","Manmohan Singh"],"answer":0,"explanation":"D. P. Dhar, as Deputy Chairman of the Planning Commission, prepared the Fifth Plan draft. Gadgil was associated with the Fourth Plan and Nanda with the early Plans.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-192","question":"Which feature distinguishes imperative (directive) planning from indicative planning?","options":["In imperative planning, targets are only forecasts meant to guide private firms’ choices","In imperative planning, the State fixes targets and enforces them by controlling resources","In imperative planning, the private sector sets targets and the State only offers incentives","In imperative planning, there are no numerical targets at all, only broad policy goals"],"answer":1,"explanation":"Imperative planning, as in the Soviet model, directs production and resources by command. Indicative planning sets broad targets and steers a market economy through incentives and public investment, the path India took from the Eighth Plan.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-193","question":"Assertion (A): An outgoing government presents an interim budget in a general election year. Reason (R): The Constitution forbids any change in tax rates in an interim budget.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"An interim budget with a vote on account is presented so that the new government can frame the full Budget. Avoiding major tax changes in it is only a convention; the Constitution does not mention interim budgets at all.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-194","question":"How many of these statements about the voting of the Union Budget are correct? I. No demand for a grant can be made except on the recommendation of the President. II. The Lok Sabha may increase the amount of a demand for grant. III. The Rajya Sabha may discuss the Budget but does not vote on the demands for grants. IV. Expenditure charged on the Consolidated Fund may be discussed but is not put to the vote.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (Article 113(3)), III and IV are correct. The Lok Sabha can assent to, refuse or reduce a demand, but cannot increase it, so II is wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-195","question":"During a boom, a government’s actual fiscal deficit falls because tax receipts surge, but its cyclically adjusted (structural) primary deficit widens. The government’s fiscal stance is best described as:","options":["Contractionary, because the actual deficit has fallen","Expansionary, because the structural deficit has widened","Neutral, because the two changes cancel out","Contractionary, because tax receipts have risen"],"answer":1,"explanation":"The fiscal stance is judged by the change in the structural primary balance, which strips out the effect of the cycle. Here discretionary policy has loosened, so the stance is expansionary and pro-cyclical, despite the smaller headline deficit.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-196","question":"In the IS–LM framework, an increase in government spending raises output the most when:","options":["The LM curve is vertical, because money demand does not depend on interest","The LM curve is horizontal, as in a liquidity trap","The IS curve is very flat, because investment is highly interest-sensitive","The central bank raises interest rates to keep the money supply fixed"],"answer":1,"explanation":"With a horizontal LM curve, interest rates do not rise as income rises, so there is no crowding out and the full multiplier works. With a vertical LM, crowding out is complete and output does not change.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-197","question":"In the Union Government’s accounts, ‘public debt’ under the Consolidated Fund of India does NOT include:","options":["Dated securities sold to banks and other investors in the market","Treasury bills of 91, 182 and 364 days issued by the Centre","Loans taken from multilateral agencies such as the World Bank","Provident fund and small savings liabilities in the Public Account"],"answer":3,"explanation":"Public debt covers internal debt (dated securities, Treasury bills and so on) and external debt raised against the Consolidated Fund. Provident funds, small savings and reserve funds are ‘other liabilities’ held in the Public Account.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-198","question":"In India, anti-dumping duty on imports is imposed by:","options":["The Ministry of Commerce, on the advice of the Department of Revenue","The Ministry of Finance, on the recommendation of the DGTR","The Central Board of Indirect Taxes, on the advice of the RBI","The GST Council, on the recommendation of the Ministry of Commerce"],"answer":1,"explanation":"The Directorate General of Trade Remedies, under the Commerce Ministry, investigates dumping and recommends a duty; the Ministry of Finance (Department of Revenue) decides and notifies it under the Customs Tariff Act.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-199","question":"For a supplier dealing only in goods in most States, GST registration becomes compulsory once aggregate turnover in a financial year exceeds:","options":["₹10 lakh","₹20 lakh","₹75 lakh","₹40 lakh"],"answer":3,"explanation":"Since 2019 the threshold for suppliers of goods is ₹40 lakh in most States, while it is ₹20 lakh for service providers; lower limits apply in some special category States.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-200","question":"Which provision of the Constitution requires the Annual Financial Statement to show expenditure on revenue account separately from other expenditure?","options":["Article 112(2)","Article 113(1)","Article 114(3)","Article 266(1)"],"answer":0,"explanation":"Article 112(2) requires the estimates to show charged and voted expenditure separately and to distinguish revenue-account expenditure from other expenditure; this is the basis of the revenue–capital split.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-201","question":"Under Article 243ZD, at least what share of the members of a District Planning Committee must be elected by and from the elected members of the district-level Panchayat and the Municipalities in the district?","options":["One-half","Two-thirds","Three-fourths","Four-fifths"],"answer":3,"explanation":"Article 243ZD requires not less than four-fifths of DPC members to be so elected, in proportion to the rural and urban populations of the district. The DPC consolidates the plans of Panchayats and Municipalities.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-202","question":"Under the rationalisation of centrally sponsored schemes in 2016, the Centre–State funding ratio for ‘core’ schemes in the North-Eastern and Himalayan States is generally:","options":["60:40","75:25","90:10","100:0"],"answer":2,"explanation":"Core schemes are generally shared 60:40 with most States and 90:10 with the North-Eastern and Himalayan States; ‘core of the core’ schemes such as MGNREGA follow their own, more generous patterns.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-203","question":"In the run-up to GST, the ‘revenue neutral rate’ studied by the committee under Arvind Subramanian (2015) meant:","options":["The single rate at which GST would yield the same revenue as the taxes it replaced","The lowest GST rate at which no good or service would remain wholly untaxed","The rate at which the Centre and the States would get exactly equal shares of GST","The rate that would leave consumer price inflation unchanged after GST came in"],"answer":0,"explanation":"The revenue neutral rate is the rate that keeps total revenue unchanged after the switch to GST. The committee used it to guide the standard rate, which then had to be set alongside lower and higher slabs.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-204","question":"The Tax Administration Reform Commission, which reported in 2014 on reforming India’s tax departments, was chaired by:","options":["Vijay Kelkar","Raja J. Chelliah","Parthasarathi Shome","Arvind Subramanian"],"answer":2,"explanation":"The Commission set up in 2013 under Parthasarathi Shome studied the working of the direct and indirect tax administrations. Kelkar and Chelliah led earlier tax reform panels, and Subramanian the GST rate committee.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-205","question":"A government’s tax revenue grows by 12% in a year in which nominal GDP grows by 10%. New tax measures account for 4 percentage points of the revenue growth. Its tax buoyancy and tax elasticity are about:","options":["0.8 and 1.2","1.2 and 1.2","1.2 and 0.8","1.6 and 0.8"],"answer":2,"explanation":"Buoyancy uses total revenue growth: 12/10 = 1.2. Elasticity strips out discretionary changes: (12 − 4)/10 = 0.8. So without new measures, revenue would have lagged GDP.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-206","question":"A dealer buys goods from another State for ₹1,00,000 plus 18% IGST and sells them within his own State for ₹1,50,000 plus 18% GST (CGST + SGST). After using input tax credit, how much GST in total must he pay in cash?","options":["₹27,000","₹13,500","₹4,500","₹9,000"],"answer":3,"explanation":"Output tax = 18% of 1,50,000 = ₹27,000; IGST credit of ₹18,000 can be set off against CGST and SGST, leaving ₹9,000. Paying only the CGST share of the margin (₹4,500) misses the SGST half.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-207","question":"The committee set up by the Union Government in 2016 to examine shifting India’s financial year from April–March to another period was headed by:","options":["Bimal Jalan","C. Rangarajan","Y. V. Reddy","Shankar Acharya"],"answer":3,"explanation":"Former Chief Economic Adviser Shankar Acharya headed the committee. Changing the year was discussed in the context of matching the budget cycle to the agricultural season, but the April–March year continues.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-208","question":"The colonial practice of presenting the Union Budget at 5 p.m. was changed to 11 a.m. with the Budget presented in:","options":["1991","1999","2001","2017"],"answer":1,"explanation":"Yashwant Sinha presented the Budget at 11 a.m. on 27 February 1999, ending a convention timed to suit London. In 2017 the date, not the time, was moved to 1 February.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-planning-budget-209","question":"Guarantees given by the Government of India on loans raised by public sector enterprises are best described as:","options":["Part of the fiscal deficit in the year in which they are given","Capital expenditure, since they help public enterprises create assets","Revenue expenditure, since the borrower repays nothing to the government","Contingent liabilities that become a charge only if the borrower defaults"],"answer":3,"explanation":"A guarantee does not involve spending when given, so it is not in the deficit, but it is a potential claim on the budget if the borrower fails to pay. That is why guarantees are disclosed and capped under fiscal rules.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-210","question":"Under Article 285, the property of the Union is exempt from:","options":["All State and local taxes, unless Parliament by law provides otherwise","Union taxes only, while taxes imposed by States and local bodies still apply","Taxes on income only, while taxes on property and goods still apply to it","Taxes of local bodies only, while taxes imposed by State legislatures apply"],"answer":0,"explanation":"Article 285 shields Union property from State and local taxes unless Parliament provides otherwise, so municipalities often get ‘service charges’ instead. Article 289 gives a matching shield to State property from Union taxes.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-211","question":"The proviso to Article 275(1) provides grants from the Consolidated Fund of India to States specifically for:","options":["Meeting the revenue deficits that remain after tax devolution to the States","Compensating States for the revenue they lost when GST was introduced","Disaster relief routed through the State Disaster Response Funds","Tribal welfare schemes and better administration of Scheduled Areas"],"answer":3,"explanation":"Article 275(1) gives statutory grants to States in need, and its proviso adds grants for tribal welfare schemes and for raising the level of administration of Scheduled Areas. GST compensation came under a separate 2017 law.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-212","question":"A ‘soft budget constraint’, a term coined by János Kornai, arises when:","options":["A government sets spending ceilings that it can legally relax during a recession","A household faces a budget line that shifts outward as its income rises","A central bank allows the government to overdraw its account for a few days","A loss-making firm expects a State bailout and so does little to control costs"],"answer":3,"explanation":"Kornai described firms in socialist economies, and later many public enterprises, whose losses were routinely covered by the State. Expecting bailouts weakens discipline, which is a key argument for hard budgets and disinvestment.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-213","question":"A government’s revenue receipts are ₹25 lakh crore and its interest payments equal 40% of revenue receipts. If its fiscal deficit is ₹16 lakh crore, its primary deficit is:","options":["₹10 lakh crore","₹9.6 lakh crore","₹6 lakh crore","₹26 lakh crore"],"answer":2,"explanation":"Interest = 0.4 × 25 = ₹10 lakh crore, so the primary deficit = 16 − 10 = ₹6 lakh crore. Taking 60% of the fiscal deficit (9.6) wrongly applies the interest share to the deficit.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-214","question":"While the Planning Commission existed, the final approval of a draft Five-Year Plan before it was placed in Parliament was given by:","options":["The National Development Council","The Union Council of Ministers","The Finance Commission of India","The Inter-State Council"],"answer":0,"explanation":"After the Planning Commission and the Union Cabinet had cleared the draft, the National Development Council (set up in 1952, with all Chief Ministers) gave the final approval. This gave States a voice in national planning.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-215","question":"For which of these taxes do the impact and the incidence normally fall on the same person?","options":["Personal income tax","Customs duty on imported cars","GST on a packet of biscuits","Excise duty on cigarettes"],"answer":0,"explanation":"Personal income tax is paid by the person who bears it, so it cannot be shifted. Indirect taxes such as GST, customs and excise are paid by sellers or importers but are largely passed on to buyers.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-216","question":"The CAG’s audit reports on the accounts of the Union are submitted to:","options":["The Speaker of the Lok Sabha, who refers them to the PAC","The Union Finance Minister, who presents them with the Budget","The President, who causes them to be laid before Parliament","The Chairman of the Public Accounts Committee directly"],"answer":2,"explanation":"Under Article 151, the CAG submits Union audit reports to the President, who has them laid before each House; the Public Accounts Committee then examines them. State reports go to the Governor.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-217","question":"A government’s fiscal deficit is ₹9 lakh crore and its revenue deficit ₹5 lakh crore. Its non-debt capital receipts are ₹1 lakh crore. Its capital expenditure is:","options":["₹4 lakh crore","₹5 lakh crore","₹3 lakh crore","₹14 lakh crore"],"answer":1,"explanation":"Fiscal deficit = revenue deficit + capital expenditure − non-debt capital receipts, so 9 = 5 + CE − 1 and CE = ₹5 lakh crore. Forgetting the non-debt receipts gives ₹4 lakh crore.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-218","question":"Fiscal consolidation is generally considered of better quality when the deficit is cut mainly by:","options":["Postponing capital expenditure on roads, railways and irrigation projects","Raising revenue and trimming revenue expenditure while protecting capital spending","Deferring payments to suppliers and shifting borrowing to public enterprises","Selling government assets every year to meet recurring expenditure needs"],"answer":1,"explanation":"Cutting capital spending hurts future growth, and deferrals or off-budget borrowing only hide the deficit. Consolidation that comes from revenue gains and lower current spending lasts and protects growth.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-219","question":"Under Article 279A, the quorum for a meeting of the GST Council is:","options":["One-third of its total members","One-half of its total members","Two-thirds of its total members","Three-fourths of its total members"],"answer":1,"explanation":"Article 279A(7) fixes the quorum at one-half of the total members. Three-fourths is the weighted majority of members present and voting that a decision needs.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-220","question":"How many of these statements about the GST Council are correct? I. The Union Minister of State in charge of Revenue or Finance is a member. II. Its Vice-Chairperson is chosen from among the State ministers who are members. III. It may recommend a special rate for a specified period to raise resources during a natural calamity. IV. The Constitution expressly makes its recommendations binding on Parliament and the State legislatures.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III follow Article 279A. The Supreme Court held in Mohit Minerals (2022) that the Council’s recommendations are persuasive, not binding, since Article 246A gives both legislatures simultaneous power; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-221","question":"The nationalisation of 14 major commercial banks in July 1969 took place during which plan period?","options":["The Third Five-Year Plan","The Annual Plans (Plan Holiday)","The Fourth Five-Year Plan","The Fifth Five-Year Plan"],"answer":2,"explanation":"The Fourth Plan began in April 1969, three months before the banks were nationalised on 19 July 1969. The Plan Holiday covered 1966–69, and six more banks were nationalised in 1980, during the Sixth Plan.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-222","question":"Which Five-Year Plan comfortably beat its modest growth target of about 2.1% a year, helped by good harvests?","options":["The First Plan","The Second Plan","The Third Plan","The Fourth Plan"],"answer":0,"explanation":"The First Plan (1951–56), focused on agriculture and irrigation, achieved growth of about 3.6% against a target of 2.1%. The Third Plan, by contrast, fell badly short because of wars and drought.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-223","question":"In public finance, ‘fiscal marksmanship’ refers to:","options":["The ability of tax officials to target evaders with data analytics","The accuracy of budget estimates compared with the actual outcomes","The success of a government in meeting its FRBM deficit targets","The precision with which subsidies reach the intended beneficiaries"],"answer":1,"explanation":"Fiscal marksmanship measures how close budget estimates of receipts and spending come to actuals; large gaps weaken the credibility of the budget. Meeting deficit targets and targeting subsidies are different issues.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-224","question":"When the Union Budget for the coming year is presented on 1 February, the figures shown for the financial year that is then ending are:","options":["Actuals","Budget Estimates","Provisional Actuals","Revised Estimates"],"answer":3,"explanation":"Each Budget shows Actuals for the year before last, Budget and Revised Estimates for the current year, and Budget Estimates for the next year. Since the current year is not over, only revised estimates are available for it.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-225","question":"In studies of Indian subsidies, those on elementary education, primary health and sanitation are usually classed as:","options":["Merit subsidies, because their benefits spread well beyond the user","Non-merit subsidies, because they go to private consumption","Hidden subsidies, because they are not shown in the budget","Cross-subsidies, because richer users pay for poorer ones"],"answer":0,"explanation":"Merit subsidies support goods with large external benefits that the market would under-supply. Subsidies on goods with mainly private benefits, such as many fuel and power subsidies, are classed as non-merit.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-226","question":"A government taxes tobacco heavily partly because people tend to underestimate its harm to their own health. Here tobacco is being treated as a:","options":["Public good","Merit good","Demerit good","Giffen good"],"answer":2,"explanation":"Demerit goods are those whose consumption the State discourages because people undervalue the harm to themselves; ‘sin taxes’ follow from this. A Pigouvian tax, by contrast, targets harm done to others.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-227","question":"The ‘free-rider problem’ explains why markets tend to under-provide:","options":["Goods whose prices are fixed by the government below cost","Goods that are rival and excludable, such as food grains","Goods produced by monopolies with very high fixed costs","Goods people can enjoy without paying, such as street lights"],"answer":3,"explanation":"When people cannot be excluded, each hopes to benefit from others’ payments, so private sellers cannot cover costs and the good is under-supplied. That is the case for public provision paid for by taxes.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-228","question":"A toll on a highway, paid only by the vehicles that use it, follows the:","options":["Ability-to-pay principle","Benefit principle","Principle of vertical equity","Principle of tax neutrality"],"answer":1,"explanation":"Under the benefit principle, people pay in proportion to the benefit they get from a public service, as toll payers do. The ability-to-pay principle links tax to income or wealth instead.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-planning-budget-229","question":"Wealth tax was abolished in India by the Budget of:","options":["2005–06","2010–11","2017–18","2015–16"],"answer":3,"explanation":"The 2015–16 Budget abolished wealth tax, which cost more to collect than it raised, and replaced it with a higher surcharge on the incomes of the very rich.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-230","question":"Arrange the abolition of these taxes in time order: 1. Wealth tax  2. Estate duty  3. Fringe benefit tax  4. Gift tax","options":["2, 4, 3, 1","4, 2, 3, 1","2, 4, 1, 3","2, 3, 4, 1"],"answer":0,"explanation":"Estate duty went in 1985, gift tax in 1998, fringe benefit tax (brought in in 2005) in 2009, and wealth tax with the 2015–16 Budget.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-231","question":"Under the corporate tax reform of 2019, existing domestic companies that give up specified exemptions and incentives may pay income tax at a base rate of:","options":["15%","25%","22%","30%"],"answer":2,"explanation":"Section 115BAA offered a 22% base rate to domestic companies forgoing exemptions; 15% was offered under Section 115BAB to new manufacturing companies, and 25% and 30% were the earlier rates.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-232","question":"A hotel in Goa lets a room to a business guest whose company is registered in Delhi. Which GST applies to the room charges?","options":["CGST and SGST of Goa, as the place of supply is the hotel’s location","IGST, because the supplier and the recipient are in different States","CGST and SGST of Delhi, because the recipient is registered there","IGST, split equally between the governments of Goa and Delhi"],"answer":0,"explanation":"For services tied to immovable property, such as accommodation, the place of supply is the location of the property. Since supplier and place of supply are both in Goa, it is an intra-State supply attracting CGST and Goa SGST.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-233","question":"Under GST, imports of goods into India are treated as:","options":["Exempt supplies, as customs duty already applies","Supplies in the course of inter-State trade, attracting IGST","Intra-State supplies, attracting CGST and SGST of the port State","Zero-rated supplies, with a refund of input tax credit"],"answer":1,"explanation":"The Constitution treats imports as inter-State supplies, so IGST is collected along with basic customs duty and its credit flows to the importer; it is zero-rating that applies to exports.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-234","question":"A government is said to be falling into a ‘debt trap’ when:","options":["It borrows mainly to pay interest on old debt, so its debt snowballs","Its debt is held mostly by foreign investors who can pull out suddenly","It borrows at fixed rates just before market interest rates fall","Its revenue deficit is zero but its fiscal deficit stays positive"],"answer":0,"explanation":"In a debt trap, fresh borrowing goes largely into interest payments, so debt keeps rising faster than revenue and GDP. A zero revenue deficit with a fiscal deficit means borrowing goes to capital spending, a healthier case.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-235","question":"In the Seventh Schedule, the subject ‘Economic and social planning’ is placed in the:","options":["Union List","State List","Eleventh Schedule only","Concurrent List"],"answer":3,"explanation":"It is Entry 20 of the Concurrent List, so both the Union and the States can plan. The Planning Commission and NITI Aayog were both set up by executive resolution, not by law under this entry.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-236","question":"For an individual who also has non-agricultural income, agricultural income under the Income-tax Act is:","options":["Taxed by the Union at the same slab rates as all other income it earns","Exempt, but counted to fix the tax rate on the non-agricultural income","Exempt, and left out completely when the person’s tax is worked out","Taxed by the Union at a lower flat rate than the person’s other income"],"answer":1,"explanation":"Taxing agricultural income is a State subject, so the Union exempts it, but under ‘partial integration’ it is added to compute the rate applicable to the non-agricultural income, which pushes that income into higher slabs.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-237","question":"Securities issued under the Market Stabilisation Scheme (MSS), introduced in 2004:","options":["Are sold by the RBI from its own stock to finance the government’s fiscal deficit","Are issued by the State governments to fund schemes that stabilise farm prices","Are issued by banks to the RBI to meet their statutory liquidity ratio needs","Are issued by the government to mop up surplus liquidity, with the money kept unspent"],"answer":3,"explanation":"MSS bonds are government securities issued to sterilise liquidity, mainly from capital inflows. The proceeds sit in a separate account with the RBI and do not fund spending, so only the interest cost affects the budget.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-238","question":"The term ‘Hindu rate of growth’, used for India’s slow growth of about 3.5% a year from the 1950s to the 1970s, was coined by:","options":["Jagdish Bhagwati","Raj Krishna","Amartya Sen","K. N. Raj"],"answer":1,"explanation":"Economist Raj Krishna coined the phrase to describe persistently low growth under the planned, controlled economy. Bhagwati was a leading critic of the licence regime but did not coin the term.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-239","question":"The Union’s gross tax revenue is ₹35 lakh crore, of which ₹5 lakh crore comes from cesses and surcharges; ignore the cost of collection. If the States’ share of the divisible pool is 41% and one State’s share of that is 4%, the State receives about:","options":["₹57,400 crore","₹1,20,000 crore","₹49,200 crore","₹50,400 crore"],"answer":2,"explanation":"Cesses and surcharges are outside the divisible pool, so the pool is ₹30 lakh crore; 41% of it is ₹12.3 lakh crore and 4% of that is ₹49,200 crore. Using the gross ₹35 lakh crore gives ₹57,400 crore.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-planning-budget-240","question":"A per-unit tax of ₹8 is levied on a good. Near the market equilibrium the price elasticity of supply is 1.5 and of demand −0.5. By about how much does the price paid by buyers rise?","options":["₹2","₹4","₹8","₹6"],"answer":3,"explanation":"Buyers’ share of the tax = Es/(Es + |Ed|) = 1.5/2 = 75%, so their price rises by ₹6 and sellers bear ₹2. The less elastic side of the market bears more of the tax.","difficulty":"very-hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-241","question":"A government’s debt is 80% of GDP and the average interest rate on it is 7.5%. If its fiscal deficit is 5% of GDP, its primary balance is:","options":["A primary deficit of 1% of GDP","A primary surplus of 1% of GDP","A primary deficit of 5% of GDP","A primary deficit of 11% of GDP"],"answer":1,"explanation":"Interest = 0.075 × 80 = 6% of GDP, which exceeds the 5% fiscal deficit, so the primary balance is a surplus of 1% of GDP. Its whole deficit is due to past debt.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-242","question":"The Integrated Rural Development Programme, after pilots in the late 1970s, was extended to all blocks of the country during the:","options":["Fourth Plan","Fifth Plan","Sixth Plan","Eighth Plan"],"answer":2,"explanation":"IRDP was extended nationwide on 2 October 1980, at the start of the Sixth Plan (1980–85), whose central aim was the removal of poverty. In 1999 it was merged into the Swarnjayanti Gram Swarozgar Yojana.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-243","question":"Under the ‘rule of lapse’ in government budgeting, money voted for a year that remains unspent on 31 March:","options":["Is carried forward automatically to the same scheme next year","Is transferred to the Contingency Fund of India for later use","Lapses and can be spent later only with fresh authorisation","Is credited to the Public Account as a reserve for that ministry"],"answer":2,"explanation":"Grants are valid only for the year, so unspent balances lapse to the Consolidated Fund. This is one cause of the ‘March rush’ of spending that the Public Accounts Committee has often criticised.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-planning-budget-244","question":"Assertion (A): If a government’s revenue deficit is zero, all its borrowing in that year goes into capital expenditure and net lending. Reason (R): The fiscal deficit equals the revenue deficit plus capital expenditure minus non-debt capital receipts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With a zero revenue deficit, the fiscal deficit equals capital spending (including loans) not covered by non-debt receipts, so borrowing is used only to build assets. This is the logic of the ‘golden rule’.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-planning-budget-245","question":"Match the Second Plan steel plant with the country that helped build it: A. Bhilai  B. Rourkela  C. Durgapur; 1. United Kingdom  2. Soviet Union  3. West Germany","options":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"answer":0,"explanation":"Bhilai was built with Soviet help, Rourkela with West German help and Durgapur with British help, reflecting the Second Plan’s push for basic and heavy industry in the public sector.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-planning-budget-246","question":"Government borrowing is least likely to crowd out private investment when:","options":["The economy is at full employment and the central bank holds money supply fixed","Private investment spending is highly sensitive to changes in the rate of interest","The government borrows heavily from domestic banks at the peak of a boom","The economy has large idle capacity and the central bank keeps interest rates steady"],"answer":3,"explanation":"Crowding out works through higher interest rates and scarce resources. With idle capacity and accommodative monetary policy, extra spending raises output and may even ‘crowd in’ investment.","difficulty":"hard","source":"RBI Grade B"},
  {"id":"eco-planning-budget-247","question":"Statutory grants-in-aid to States under Article 275 are:","options":["Voted each year by the Lok Sabha as part of the demands for grants","Charged on the Consolidated Fund of India","Paid from the Contingency Fund of India","Given at the discretion of the Union Finance Ministry"],"answer":1,"explanation":"Article 275(1) charges these grants on the Consolidated Fund of India, so they are not voted, and they are made on the Finance Commission’s recommendation. Discretionary grants come under Article 282.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-planning-budget-248","question":"Which of these is a ‘blocked credit’, i.e. input tax credit that cannot be claimed, under the GST law?","options":["GST paid on raw materials used in manufacturing","GST paid on computers bought for the office","GST paid on club membership for an employee","GST paid on freight to deliver goods to buyers"],"answer":2,"explanation":"Section 17(5) of the CGST Act blocks credit on items of personal consumption such as club membership, food and beverages and most motor vehicles. Inputs, capital goods and input services used for business qualify.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-planning-budget-249","question":"Which of the following is a non-tax revenue receipt of the Union Government?","options":["Corporation tax collected from companies on their profits","Customs duty collected on imports of gold and silver","Proceeds from selling part of the government’s stake in a PSU","Dividends from PSUs and the surplus transferred by the RBI"],"answer":3,"explanation":"Non-tax revenue includes dividends and profits, interest receipts and fees. Corporation tax and customs are tax revenue, and disinvestment proceeds are non-debt capital receipts, not revenue.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-planning-budget-250","question":"An income-tax ‘surcharge’ is best described as:","options":["An additional tax on the tax payable, applied mainly to higher incomes","A tax levied for a specified purpose such as health and education","A penalty charged for filing the income-tax return after the due date","A tax collected at source by banks on large cash withdrawals"],"answer":0,"explanation":"A surcharge is a percentage of the tax already payable, used to raise the burden on high earners; a cess is earmarked for a stated purpose. Neither forms part of the divisible pool shared with States.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
];

export default questions;
